# Encontros 61 a 72: redação (estrutura do texto dissertativo-argumentativo e as 5 competências do ENEM).
from base import M, A, VF, C, T, E

B = 'Redação: estrutura'

E(61, B, 'O texto dissertativo-argumentativo e as 5 competências do ENEM',
  aquecimento='Quem já ouviu falar da redação do ENEM? Na opinião de vocês, o que pesa mais na nota: escrever bonito ou defender bem uma ideia, e por quê?',
  quadro=['# O que é o texto dissertativo-argumentativo',
    '- Texto em prosa que defende um ponto de vista (a tese) sobre um problema social, com argumentos e uma proposta de solução.',
    '- Dissertar = expor e discutir ideias. Argumentar = convencer o leitor com razões, fatos e exemplos.',
    '- Não é narração (não conta uma história), nem carta, nem poema, nem lista de tópicos.',
    '# A estrutura em 4 parágrafos',
    '- Introdução: contextualiza o tema e apresenta a tese (o ponto de vista).',
    '- Desenvolvimento 1 (D1): defende o primeiro argumento, com explicação e repertório.',
    '- Desenvolvimento 2 (D2): defende o segundo argumento, com explicação e repertório.',
    '- Conclusão: retoma a tese e apresenta a proposta de intervenção (uma solução detalhada para o problema).',
    '# Regras de forma',
    '- Extensão: no máximo 30 linhas. Com até 7 linhas, a redação é zerada. O ideal é escrever de 25 a 30 linhas.',
    '- Linguagem: norma-padrão e vocabulário formal, sem gírias, abreviações ou marcas da fala.',
    '- Impessoalidade: prefira a 3ª pessoa. Em vez de “Eu acho que a escola deve…”, escreva “Cabe à escola…”.',
    '- Título: é opcional. Só vale o texto passado a limpo, a caneta preta, na folha de redação (o rascunho não é corrigido).',
    '# As 5 competências (cada uma vale de 0 a 200 pontos; total: 1000)',
    '- C1: domínio da modalidade escrita formal (norma-padrão) da língua portuguesa.',
    '- C2: compreender a proposta e desenvolver o tema no tipo dissertativo-argumentativo, com repertório de várias áreas.',
    '- C3: selecionar, relacionar, organizar e interpretar informações em defesa de um ponto de vista (projeto de texto).',
    '- C4: usar os mecanismos linguísticos de coesão (conectivos, referenciação) na construção da argumentação.',
    '- C5: elaborar uma proposta de intervenção para o problema, respeitando os direitos humanos.',
    '# O que zera a redação',
    '- Fuga total ao tema; não atender ao tipo dissertativo-argumentativo; texto com até 7 linhas; folha de redação em branco.',
    '- Cópia integral dos textos motivadores; parte do texto propositalmente desconectada do tema.',
    '- Desenhos ou ofensas propositais; nome, assinatura ou apelido escritos fora do local indicado.',
    '# Fique atento',
    '- Tangenciar o tema (tratar só do assunto geral, sem o recorte) não zera, mas derruba muito a nota (C2, C3 e C5).',
    '- Ex.: no tema de 2017, “Desafios para a formação educacional de surdos no Brasil”, falar só de “educação no Brasil” é tangenciar.',
    '- Antes de escrever, leia a frase-tema com atenção e sublinhe as palavras-chave.'],
  q=[M('Qual é a estrutura mais usada na redação do ENEM?', ['introdução, dois parágrafos de desenvolvimento e conclusão', 'apresentação, complicação, clímax e desfecho da história', 'saudação, assunto principal, despedida e assinatura', 'introdução, lista de tópicos numerados e conclusão'], 0),
     M('No modelo estudado, em qual parte da redação aparece a proposta de intervenção?', ['na conclusão', 'na introdução', 'no primeiro desenvolvimento', 'no título'], 0),
     M('O que acontece com uma redação do ENEM que tem apenas 7 linhas?', ['recebe nota zero', 'é corrigida normalmente', 'perde pontos só na Competência 1', 'ganha nota máxima se não tiver erros'], 0),
     M('Qual frase respeita a impessoalidade recomendada na redação?', ['É necessário ampliar o acesso à cultura nas periferias.', 'Eu acho que todo mundo devia ir mais ao cinema.', 'Na minha opinião, você precisa ler mais livros.', 'Sinceramente, a gente não aguenta mais esse problema.'], 0),
     T('(1) No curta “Ilha das Flores” (1989), de Jorge Furtado, pessoas disputam com porcos os restos de comida de um lixão. A cena ainda revela um paradoxo atual: o Brasil desperdiça alimentos enquanto parte da população passa fome. Esse quadro decorre da falta de educação para o consumo e da ausência de políticas de doação. '
       '(2) Em primeiro lugar, muitas famílias compram mais do que consomem e descartam comida em bom estado, por desconhecerem formas de reaproveitamento. '
       '(3) Além disso, supermercados e restaurantes jogam fora produtos ainda próprios para consumo, pois faltam incentivos e regras claras para a doação. '
       '(4) Portanto, para reduzir o desperdício, o Governo Federal deve criar, em parceria com redes de supermercados, um programa de doação de alimentos, por meio de incentivos fiscais e de pontos de coleta, a fim de levar comida a quem precisa.',
       fonte='Texto elaborado para esta atividade (redação em miniatura: na prova, cada parágrafo é mais longo).', titulo='Desperdício de alimentos', para=4),
     M('Em qual parágrafo o autor apresenta a tese pela primeira vez?', ['no parágrafo 1', 'no parágrafo 2', 'no parágrafo 3', 'no parágrafo 4'], 0),
     A('Qual repertório o autor usou na introdução? A que área do conhecimento ele pertence?', 'O curta “Ilha das Flores” (1989), de Jorge Furtado: repertório do cinema (artes).'),
     M('O parágrafo 4 é a conclusão porque:', ['retoma o problema e apresenta uma proposta de intervenção', 'conta uma experiência pessoal vivida pelo autor', 'apresenta o primeiro argumento, com um exemplo', 'faz uma pergunta e deixa o leitor sem resposta'], 0),
     A('No parágrafo 4, identifique quem deve agir (agente) e o que deve ser feito (ação).', 'Agente: o Governo Federal (em parceria com redes de supermercados); ação: criar um programa de doação de alimentos.', 2),
     M('A Competência 5 avalia:', ['a proposta de intervenção que respeita os direitos humanos', 'o domínio da norma-padrão da língua escrita', 'o uso de conectivos e da referenciação', 'a seleção e a organização dos argumentos'], 0),
     M('O uso de conectivos para ligar frases e parágrafos é avaliado principalmente na:', ['Competência 4', 'Competência 1', 'Competência 2', 'Competência 5'], 0),
     M('Tema: “Democratização do acesso ao cinema no Brasil” (ENEM 2019). Qual texto TANGENCIA o tema?', ['um texto sobre a importância da arte e da cultura em geral', 'um texto sobre o preço dos ingressos, que afasta muitos brasileiros do cinema', 'um texto sobre a falta de salas de cinema nas cidades pequenas e nas periferias', 'um texto sobre como levar sessões de cinema às escolas públicas'], 0),
     VF('Marque V ou F sobre a redação do ENEM:', [('O título é obrigatório.', False), ('O texto deve ser escrito em prosa, e não em versos.', True), ('Cada competência vale de 0 a 200 pontos.', True), ('O rascunho também é corrigido e pode aumentar a nota.', False), ('A fuga total ao tema zera a redação.', True)]),
     C('Associe cada competência ao que ela avalia:', [('Competência 1', 'norma-padrão da língua escrita'), ('Competência 2', 'compreensão da proposta, tipo textual e repertório'), ('Competência 3', 'seleção e organização das ideias (projeto de texto)'), ('Competência 4', 'coesão: conectivos e referenciação'), ('Competência 5', 'proposta de intervenção')]),
     A('Reescreva a frase de forma impessoal: “Eu acho que nós precisamos cuidar melhor dos nossos idosos.”', 'Ex.: É necessário cuidar melhor dos idosos. / A sociedade precisa cuidar melhor das pessoas idosas.', 2),
     A('Complete com as palavras do quadro: A redação do ENEM é um texto ____, escrito em prosa, com no máximo ____ linhas, na ____ e com uma proposta de ____ no final.', 'dissertativo-argumentativo; 30; norma-padrão; intervenção.', 2, banco=['dissertativo-argumentativo', '30', 'norma-padrão', 'intervenção', 'narrativo', '15']),
     A('Explique a diferença entre fugir do tema e tangenciar o tema.', 'Fugir do tema é escrever sobre outro assunto (a redação é zerada); tangenciar é tratar só do assunto geral, sem o recorte pedido (a nota cai muito).', 2),
     A('Cite três situações que zeram a redação do ENEM.', 'Ex.: fuga total ao tema; texto com até 7 linhas; não atender ao tipo dissertativo-argumentativo (também: folha em branco, cópia integral dos textos motivadores, parte desconectada, desenhos ou ofensas).', 2),
  ],
  producao='Tema: “Desafios para a valorização da leitura entre os jovens brasileiros”. Escreva o esqueleto da sua redação em 4 frases, uma para cada parágrafo: 1) introdução com a tese; 2) primeiro argumento; 3) segundo argumento; 4) conclusão com uma solução (quem deve fazer o quê). Use a 3ª pessoa e a norma-padrão.')

E(62, B, 'Competência 1: os desvios mais comuns da norma-padrão na redação',
  aquecimento='Jogo “da fala para a escrita”: o professor diz frases bem informais (“Tipo, a gente tá cansado, né?”) e a turma, oralmente, transforma cada uma em linguagem formal.',
  quadro=['# O que a Competência 1 avalia',
    '- O domínio da norma-padrão: ortografia, acentuação, pontuação, concordância, regência e construção das frases.',
    '- Também avalia a escolha das palavras: nada de gírias, abreviações e marcas da fala.',
    '# Concordância e regência',
    '- Concordância verbal: Existem muitos problemas. / Há muitos problemas (haver = existir fica no singular). / Faz dez anos.',
    '- Concordância nominal: medidas urgentes; políticas públicas eficazes; É necessária a participação de todos.',
    '- Regência: assistir ao debate; obedecer às leis; preferir ler a assistir à TV (sem “mais” e sem “do que”); o direito à educação.',
    '# Crase e acentuação',
    '- Crase = preposição a + artigo a (acesso à saúde, devido à falta de) e locuções femininas (à medida que). Não há crase antes de verbo nem de palavra masculina: a partir de, a pé.',
    '- Acentos que mais faltam na redação: público, política, saúde, possível, também, além, país, através, eles têm.',
    '# Vírgula',
    '- Nunca separe o sujeito do verbo: “A falta de investimentos, prejudica os jovens.” (errado) → “A falta de investimentos prejudica os jovens.”',
    '- Use vírgula depois de expressão deslocada no início (“No Brasil, muitos jovens…”) e antes de “mas”.',
    '# Palavras que confundem',
    '- Mal (oposto de bem) x mau (oposto de bom): O país investe mal. / Um mau exemplo.',
    '- Há (= faz, existe) x a (tempo futuro, distância): Há anos o problema persiste. / Daqui a dois anos.',
    '- Por que (pergunta; = pelo qual), porque (causa, resposta), por quê (fim de frase), porquê (substantivo: o porquê).',
    '- Onde: só para lugar físico. Para tempo ou situação, use “em que”, “no qual”: “Vivemos uma época em que…”.',
    '# Frases completas e linguagem formal',
    '- Frase fragmentada: “Porque o governo não investe.” sozinha está incompleta. Junte-a à oração principal: “O problema persiste porque o governo não investe.”',
    '- Marcas de oralidade: tipo, aí, né, então assim, a gente, tá, pra. Use: por exemplo, assim, a sociedade, está, para.',
    '- Gírias e abreviações: “galera”, “bombar”, “vc”, “tb”, “q”, “pq”, “mto”. Escreva as palavras por extenso e no registro formal.',
    '# Fique atento',
    '- Revise procurando um tipo de erro por vez: primeiro a concordância, depois as vírgulas, depois os acentos.',
    '- Frases muito longas multiplicam os erros: prefira períodos curtos e claros.',
    '- Na dúvida sobre uma palavra, troque-a por um sinônimo que você saiba escrever.'],
  q=[M('Qual frase está de acordo com a norma-padrão?', ['Existem muitos desafios na educação brasileira.', 'Existe muitos desafios na educação brasileira.', 'Haviam muitos desafios na educação brasileira.', 'Fazem anos que existem desafios na educação.'], 0),
     M('Complete: O país investe ____ em ciência ____ décadas.', ['mal – há', 'mau – há', 'mal – a', 'mau – a'], 0),
     M('Qual alternativa NÃO apresenta marca de oralidade?', ['Por exemplo, muitos jovens não leem jornais.', 'Tipo, muitos jovens não leem jornais.', 'Aí muitos jovens não leem jornais, né?', 'Então assim, a galera não lê jornal.'], 0),
     M('Em qual frase há uma vírgula separando o sujeito do verbo (erro)?', ['A falta de saneamento básico, prejudica a saúde da população.', 'No Brasil, a falta de saneamento básico prejudica a saúde.', 'A falta de saneamento, segundo especialistas, prejudica a saúde.', 'A falta de saneamento prejudica a saúde, a economia e o ambiente.'], 0),
     M('Qual frase usa a crase corretamente?', ['O acesso à cultura é um direito de todos.', 'Os jovens começaram à estudar mais cedo.', 'A campanha foi feita à partir de março.', 'O projeto beneficiou à todos os alunos.'], 0),
     M('Em qual frase o “onde” está empregado corretamente?', ['A cidade onde moro não tem biblioteca pública.', 'A pandemia foi um período onde muitos perderam o emprego.', 'Vivemos uma situação onde o diálogo é raro.', 'O ECA é uma lei onde as crianças são protegidas.'], 0),
     M('Complete: Muitos se perguntam ____ o problema persiste; isso ocorre ____ faltam políticas públicas.', ['por que – porque', 'porque – por que', 'por quê – porque', 'porquê – por que'], 0),
     T('Atualmente, a falta de leitura entre os jovens, é um problema serio no Brasil. Tipo, muitos adolescentes passa horas no celular e não abre um livro. Aí, quando chega no ENEM, eles tem dificuldade para interpretar textos. Isso acontece por que as escolas não incentiva a leitura de forma prazerosa. Além disso, a internet trouxe uma época onde tudo é rápido, né? Porque ninguém tem paciência para ler textos longos. Assim, é preciso que as famílias e a escola ajudem os jovens a descobrir o prazer de ler.',
       fonte='Texto elaborado para esta atividade, com desvios propositais.', titulo='Parágrafo de um estudante (para revisar)', para=4),
     A('Copie do texto as três marcas de oralidade e diga o que fazer com cada uma.', '“Tipo” (trocar por “Por exemplo,”), “Aí” (trocar por “Assim,” ou “Consequentemente,”) e “né?” (retirar).', 2),
     M('No trecho “a falta de leitura entre os jovens, é um problema serio”, há:', ['vírgula entre o sujeito e o verbo e falta de acento em “sério”', 'erro de crase antes de “problema” e de concordância em “jovens”', 'uma gíria (“Atualmente”) e uma abreviação (“serio”)', 'uso inadequado do “onde” e falta de acento em “falta”'], 0),
     A('Corrija a concordância: “muitos adolescentes passa horas no celular e não abre um livro”; “eles tem dificuldade”; “as escolas não incentiva a leitura”.', 'muitos adolescentes passam horas no celular e não abrem um livro; eles têm dificuldade; as escolas não incentivam a leitura.', 2),
     A('Reescreva o trecho corrigindo o “onde”, a marca de oralidade e a frase fragmentada: “a internet trouxe uma época onde tudo é rápido, né? Porque ninguém tem paciência para ler textos longos.”', 'Ex.: Além disso, a internet trouxe uma época em que tudo é rápido; por isso, muitos já não têm paciência para ler textos longos.', 3),
     VF('Marque V ou F sobre a linguagem da redação:', [('“vc” e “tb” são abreviações que não devem aparecer na redação.', True), ('“A gente” é a forma mais adequada para o texto formal.', False), ('“Pra” deve ser substituído por “para”.', True), ('A vírgula entre o sujeito e o verbo é obrigatória em frases longas.', False), ('“Há” pode ser trocado por “faz” quando indica tempo passado.', True)]),
     M('Qual frase está fragmentada (incompleta)?', ['Porque muitas famílias não têm computador em casa.', 'Muitas famílias não têm computador em casa.', 'O acesso à internet ainda é desigual no Brasil.', 'Muitos estudantes não conseguem acompanhar as aulas on-line.'], 0),
     A('Reescreva na norma-padrão: “Fazem dez anos que a biblioteca fechou, e haviam muitos leitores na cidade.”', 'Faz dez anos que a biblioteca fechou, e havia muitos leitores na cidade.'),
     A('Corrija a regência e a crase: “Os alunos assistiram o debate e se referiram à vários autores.”', 'Os alunos assistiram ao debate e se referiram a vários autores.'),
     A('Acentue corretamente: publico – saude – possivel – pais (nação) – tambem.', 'público; saúde; possível; país; também.'),
     A('Reescreva trocando as gírias e as abreviações: “A galera tá mto ligada nas redes, pq lá tudo bomba rápido.”', 'Ex.: Os jovens estão muito conectados às redes sociais, porque nelas tudo se espalha rapidamente.', 2),
     A('Una o fragmento à oração anterior: “Muitos jovens abandonam a escola. Porque precisam trabalhar.”', 'Muitos jovens abandonam a escola porque precisam trabalhar.'),
  ],
  producao='Escreva um parágrafo de 6 a 8 linhas sobre o tema “O uso excessivo do celular entre os jovens”, sem marcas de oralidade, gírias ou abreviações. Depois, troque com um colega e revisem juntos: concordância, vírgula entre sujeito e verbo, acentos, crase e uso do “onde”.')

E(63, B, 'Competência 2: compreender a proposta e o tipo textual',
  aquecimento='O professor escreve no quadro o tema do ENEM 2018, “Manipulação do comportamento do usuário pelo controle de dados na internet”, e pergunta: o que exatamente esse tema pede, e falar da internet em geral basta?',
  quadro=['# O que a Competência 2 avalia',
    '- Se você compreendeu a proposta, se desenvolveu o tema no tipo dissertativo-argumentativo e se usou repertório de várias áreas do conhecimento.',
    '# Como é a proposta de redação do ENEM',
    '- Textos motivadores (trechos de leis, notícias, gráficos, charges) + a frase-tema + as instruções.',
    '- Os textos motivadores ajudam a pensar, mas quem define o assunto é a frase-tema: leia-a palavra por palavra.',
    '# Palavras-chave e recorte',
    '- Sublinhe as palavras-chave: elas mostram o assunto e o recorte (o aspecto exato que deve ser discutido).',
    '- Ex.: “Desafios para a valorização da herança africana no Brasil” (2024): desafios + valorização + herança africana + no Brasil.',
    '- Assunto geral: a cultura africana. Recorte: os DESAFIOS para VALORIZAR essa herança NO BRASIL.',
    '- Transforme o tema em pergunta: “Quais são os desafios para valorizar a herança africana no Brasil e como superá-los?”',
    '# O tipo textual',
    '- Dissertativo-argumentativo: defender uma tese com argumentos, em prosa, e apresentar uma proposta de intervenção.',
    '- NÃO narre uma história (“Era uma vez…”), não escreva carta (“Prezado senhor…”), poema, diálogo ou lista de tópicos.',
    '# Repertório produtivo',
    '- Repertório: conhecimento de fora dos textos motivadores (lei, livro, filme, fato histórico, pensador, dado confiável).',
    '- Bom repertório é legitimado (fonte confiável), pertinente (ligado ao tema) e produtivo (usado para provar o argumento).',
    '- Ex. (tema de 2020, estigma associado às doenças mentais): a definição de saúde da OMS (1946) inclui o bem-estar mental, e não só o físico.',
    '# Os textos motivadores',
    '- Não copie os textos motivadores: as linhas copiadas são desconsideradas, e a cópia integral zera a redação.',
    '- Use as ideias deles com suas palavras e acrescente conhecimentos próprios.',
    '# Fique atento',
    '- Repertório decorado e sem relação com o tema não ajuda: ele precisa conversar com o argumento.',
    '- Não invente citações, leis ou números: isso tira a credibilidade do texto.',
    '- Antes de escrever, confira: meu texto responde à pergunta do tema, com o recorte certo?'],
  q=[M('Na proposta de redação do ENEM, onde está o tema que deve ser desenvolvido?', ['na frase-tema, destacada nas instruções', 'no título do primeiro texto motivador', 'na charge, que sempre resume o tema', 'em qualquer frase dos textos motivadores'], 0),
     M('Qual início é adequado ao tipo dissertativo-argumentativo?', ['A invisibilidade do trabalho de cuidado feito pelas mulheres ainda é um desafio no Brasil.', 'Era uma vez uma mulher que cuidava da casa, dos filhos e dos pais sem nenhum descanso.', 'Prezado senhor presidente, venho por meio desta pedir mais ajuda para as mulheres.', 'Mulher que cuida / de todos sem descanso, / quem cuida de ti, / quem cuida do teu cansaço?'], 0),
     M('Tema: “Desafios para a formação educacional de surdos no Brasil” (ENEM 2017). Qual é o recorte do tema?', ['os desafios da formação educacional das pessoas surdas no Brasil', 'os problemas da educação brasileira em geral, em todos os níveis', 'as causas da surdez e os tratamentos médicos mais modernos', 'a história da língua de sinais em diferentes países do mundo'], 0),
     T('Texto I: A Constituição Federal de 1988, em seu artigo 6º, inclui o transporte entre os direitos sociais, ao lado da educação, da saúde e do trabalho. '
       'Texto II: Na tirinha, um rapaz espera no ponto de ônibus de um bairro afastado, olha o relógio e pensa: “Duas horas até o trabalho… de novo”. '
       'Texto III (gráfico fictício): a maioria dos moradores entrevistados em um bairro da periferia afirma gastar mais de uma hora por dia no transporte coletivo. '
       'Instrução: a partir da leitura dos textos motivadores e com base nos conhecimentos construídos ao longo de sua formação, redija um texto dissertativo-argumentativo, em modalidade escrita formal da língua portuguesa, sobre o tema “Desafios para a garantia da mobilidade urbana nas periferias brasileiras”, apresentando proposta de intervenção que respeite os direitos humanos.',
       fonte='Proposta elaborada para esta atividade (o gráfico é fictício).', titulo='Proposta de redação (simulado)', para=4),
     A('Copie as palavras-chave da frase-tema.', 'desafios; garantia; mobilidade urbana; periferias brasileiras.'),
     M('Qual tese está DENTRO do recorte do tema?', ['A distância e a precariedade do transporte coletivo dificultam a mobilidade de quem vive nas periferias.', 'O trânsito das grandes cidades do mundo é um problema antigo, que dificilmente terá solução.', 'O automóvel foi uma das invenções mais importantes da história recente da humanidade.', 'Os brasileiros precisam praticar mais caminhadas e outras atividades físicas no dia a dia.'], 0),
     M('Um estudante escreveu sobre “o trânsito no Brasil”, sem falar das periferias. Ele:', ['tangenciou o tema, o que derruba muito a nota', 'fez exatamente o recorte pedido pelo tema', 'fugiu totalmente do tema e terá nota zero', 'atendeu ao tema, pois trânsito e mobilidade são sinônimos'], 0),
     A('Explique, com suas palavras, a ideia do Texto I e diga como ela pode ser usada como argumento.', 'O transporte é um direito social garantido pela Constituição (art. 6º); pode-se argumentar que a precariedade do transporte nas periferias desrespeita esse direito.', 2),
     M('Qual pergunta resume melhor o tema “Democratização do acesso ao cinema no Brasil”?', ['Por que o acesso ao cinema ainda é desigual no Brasil e como ampliá-lo?', 'Quais são os melhores filmes brasileiros de todos os tempos e por quê?', 'Como os filmes são produzidos, distribuídos e lançados no mundo?', 'Por que as pessoas gostam tanto de assistir a filmes no fim de semana?'], 0),
     M('Um repertório é produtivo quando:', ['está ligado ao tema e é usado para comprovar o argumento', 'é uma citação famosa, mesmo sem relação com o tema', 'aparece só na introdução, como enfeite do texto', 'é copiado de um dos textos motivadores da prova'], 0),
     M('Tema: “O estigma associado às doenças mentais na sociedade brasileira” (2020). Qual repertório é mais pertinente?', ['a definição de saúde da OMS, que inclui o bem-estar mental', 'a Lei Maria da Penha, que combate a violência doméstica', 'o Marco Civil da Internet, que regula o uso da rede', 'a Rio-92, conferência da ONU sobre o meio ambiente'], 0),
     M('O que acontece quando o participante copia trechos dos textos motivadores?', ['as linhas copiadas são desconsideradas, e a cópia integral zera a redação', 'a nota aumenta, porque a cópia mostra que ele leu com atenção a proposta', 'a cópia passa a valer como repertório produtivo na Competência 2', 'a cópia é aceita em qualquer parágrafo, menos no de conclusão'], 0),
     VF('Marque V ou F sobre a Competência 2:', [('Uma redação em forma de carta não atende ao tipo textual pedido.', True), ('Tangenciar o tema é o mesmo que fugir totalmente dele.', False), ('O repertório pode vir de várias áreas: história, filosofia, leis, cinema, literatura.', True), ('Basta citar um filme qualquer para garantir a nota máxima.', False), ('Transformar o tema em pergunta ajuda a não fugir do recorte.', True)]),
     C('Associe a situação à consequência na redação do ENEM:', [('texto que narra uma história', 'não atende ao tipo textual e é zerado'), ('texto que trata só do assunto geral', 'tangencia o tema e perde muitos pontos'), ('texto sobre outro assunto', 'foge ao tema e é zerado'), ('texto com trechos copiados dos textos motivadores', 'tem as linhas copiadas desconsideradas')]),
     A('Transforme o tema “Caminhos para combater a intolerância religiosa no Brasil” (ENEM 2016) em uma pergunta.', 'Ex.: Como combater a intolerância religiosa no Brasil?'),
     A('Escreva as palavras-chave e o recorte do tema “Invisibilidade e registro civil: garantia de acesso à cidadania no Brasil” (2021).', 'Palavras-chave: invisibilidade, registro civil, acesso à cidadania, no Brasil. Recorte: como a falta de registro civil torna pessoas invisíveis e impede seu acesso à cidadania no Brasil.', 2),
     A('Explique por que um texto que começa com “Querido diário, hoje vi uma notícia sobre…” não atende à proposta.', 'Porque é um diário, isto é, um relato pessoal (narração), e não um texto dissertativo-argumentativo que defende uma tese com argumentos.', 2),
     A('Mostre como um repertório pode ser usado no tema “Desafios para a valorização de comunidades e povos tradicionais no Brasil” (2022).', 'Resposta pessoal. Ex.: Ailton Krenak, em “Ideias para adiar o fim do mundo”, mostra que os povos indígenas têm outra forma de se relacionar com a natureza; valorizar esses saberes ajuda a proteger o meio ambiente.', 3),
  ],
  producao='Tema: “Desafios para a garantia da mobilidade urbana nas periferias brasileiras”. Em 6 a 8 linhas: a) copie as palavras-chave e transforme o tema em pergunta; b) escreva sua tese em uma frase; c) indique um repertório produtivo que não esteja nos textos motivadores e explique como ele ajuda a defender a tese.')

E(64, B, 'Introdução I: contextualização, tese e anúncio dos argumentos',
  aquecimento='Como vocês começam uma conversa séria, por exemplo, para pedir algo importante aos pais ou ao chefe? O que dizem primeiro, e o que isso tem a ver com o começo de uma redação?',
  quadro=['# Para que serve a introdução',
    '- Apresenta o tema ao leitor, mostra o ponto de vista (a tese) e indica o caminho que o texto vai seguir.',
    '- Tamanho ideal: de 4 a 6 linhas, em um único parágrafo.',
    '# O modelo em 3 partes',
    '- 1) Contextualização: uma ideia mais ampla que leva ao tema, de preferência com repertório (lei, fato histórico, livro, filme, pensador).',
    '- 2) Tema e tese: apresente o problema com as palavras-chave do tema e diga qual é o seu ponto de vista sobre ele.',
    '- 3) Anúncio dos argumentos: indique as duas causas (ou aspectos) que serão discutidas no D1 e no D2.',
    '# Exemplo (tema: democratização do acesso ao cinema no Brasil, ENEM 2019)',
    '- [Contextualização] Em 1895, os irmãos Lumière realizaram em Paris uma das primeiras exibições públicas de cinema, arte que logo se tornou popular.',
    '- [Tema e tese] No Brasil, contudo, o acesso às salas de cinema ainda é restrito a uma parcela da população, o que exclui muitos cidadãos dessa forma de cultura e lazer.',
    '- [Anúncio] Esse cenário decorre da concentração das salas nos grandes centros urbanos e do alto preço dos ingressos.',
    '# Expressões úteis',
    '- Para ligar a contextualização ao tema: “No Brasil, contudo,…”, “Essa realidade, entretanto,…”, “Nesse contexto,…”.',
    '- Para anunciar os argumentos: “Esse problema decorre de… e de…”, “Tal cenário se deve a… e a…”, “Isso ocorre devido a… e a…”.',
    '# Erros comuns',
    '- Introdução sem tese: só apresenta o assunto, sem ponto de vista. Ex.: “O cinema existe há mais de cem anos e há muitos filmes.”',
    '- Anunciar e não desenvolver: os dois argumentos anunciados precisam ser exatamente os do D1 e do D2, na mesma ordem.',
    '- Frases vagas ou clichês: “Desde os primórdios da humanidade…”, “Hoje em dia, muito se fala sobre…”.',
    '- Exemplos longos ou a proposta de solução já na introdução: guarde-os para o desenvolvimento e a conclusão.',
    '# Fique atento',
    '- Use as palavras-chave do tema (ou sinônimos) na introdução: isso mostra que você entendeu o recorte.',
    '- O repertório da contextualização precisa ter relação com o tema, e não ficar solto.',
    '- Roteiro: contextualização (1 a 2 linhas) + tema e tese (1 a 2 linhas) + anúncio dos argumentos (1 a 2 linhas).'],
  q=[M('No modelo estudado, quantas linhas deve ter, em média, uma boa introdução?', ['de 4 a 6 linhas', 'de 1 a 2 linhas', 'de 10 a 12 linhas', 'de 15 a 20 linhas'], 0),
     M('Quais são as três partes do modelo de introdução estudado?', ['contextualização, tema e tese, anúncio dos argumentos', 'título, tese e proposta de intervenção completa', 'apresentação, conflito e desfecho da história', 'saudação, assunto da mensagem e despedida'], 0),
     M('Na introdução, a contextualização serve para:', ['situar o leitor e conduzi-lo ao tema', 'apresentar a proposta de intervenção', 'resumir o que será dito na conclusão', 'narrar uma experiência pessoal do autor'], 0),
     T('(I) A filósofa Simone de Beauvoir afirmou que “ninguém nasce mulher: torna-se mulher”, ou seja, os papéis atribuídos às mulheres são construídos pela sociedade. '
       '(II) No Brasil, essa construção se revela na invisibilidade do trabalho de cuidado com a casa, os filhos e os idosos, realizado em sua maioria por mulheres e raramente reconhecido como trabalho. '
       '(III) Tal cenário decorre da herança machista, que naturaliza esse papel como feminino, e da falta de políticas públicas que dividam essa responsabilidade.',
       fonte='Texto elaborado para esta atividade.', titulo='Introdução de uma estudante (tema do ENEM 2023)', para=4),
     M('O trecho (I) corresponde a qual parte da introdução?', ['contextualização com repertório', 'apresentação da tese', 'anúncio dos argumentos', 'proposta de intervenção'], 0),
     M('Qual frase resume a tese da introdução?', ['O trabalho de cuidado feito pelas mulheres é pouco reconhecido no Brasil.', 'Simone de Beauvoir foi uma das filósofas mais lidas do século XX.', 'As mulheres devem deixar de cuidar da casa, dos filhos e dos idosos.', 'O Brasil já superou a desigualdade de tarefas entre homens e mulheres.'], 0),
     A('Quais são os dois argumentos anunciados no trecho (III)?', 'A herança machista, que naturaliza o cuidado como papel feminino, e a falta de políticas públicas que dividam essa responsabilidade.', 2),
     A('Sobre o que deve tratar cada parágrafo de desenvolvimento dessa redação?', 'D1: a herança machista que naturaliza o cuidado como tarefa da mulher; D2: a falta de políticas públicas que dividam essa responsabilidade.', 2),
     M('Qual frase apresenta uma TESE?', ['A falta de acessibilidade nas cidades impede que pessoas com deficiência exerçam plenamente a cidadania.', 'As cidades brasileiras têm ruas, calçadas, praças e prédios públicos de tamanhos muito variados.', 'Existem pessoas com deficiência em todos os países do mundo e nas mais diferentes idades.', 'Muitas pessoas usam ônibus, metrô ou bicicleta para ir ao trabalho e à escola todos os dias.'], 0),
     M('Qual frase ANUNCIA os argumentos que serão desenvolvidos?', ['Esse problema decorre da falta de fiscalização e da desinformação da população.', 'Era uma vez um país que tinha muitos problemas sociais para resolver.', 'Em suma, cabe ao governo criar campanhas de conscientização nas escolas.', 'Eu acho que esse problema é muito triste e precisa acabar logo.'], 0),
     M('Um aluno anunciou na introdução “a desinformação e a falta de investimento”, mas no D2 falou da influência das redes sociais. Qual é o problema?', ['ele anunciou um argumento e não o desenvolveu', 'ele usou repertório demais no segundo parágrafo', 'ele colocou a tese no lugar errado do texto', 'ele não usou a 3ª pessoa no desenvolvimento'], 0),
     M('Qual início de introdução deve ser evitado por ser um clichê vago?', ['Desde os primórdios da humanidade, o homem busca evoluir.', 'A Constituição de 1988 garante a todos o direito à saúde.', 'Em 1888, a Lei Áurea aboliu a escravidão no Brasil.', 'O filme “Que Horas Ela Volta?” retrata a desigualdade no trabalho doméstico.'], 0),
     VF('Marque V ou F sobre a introdução:', [('A introdução deve apresentar a tese.', True), ('Uma introdução que só apresenta o assunto, sem ponto de vista, está completa.', False), ('O repertório da contextualização deve ter relação com o tema.', True), ('Os argumentos anunciados podem ser trocados por outros no desenvolvimento.', False), ('É recomendável usar as palavras-chave do tema na introdução.', True)]),
     A('Numere as frases na ordem correta para formar uma introdução: ( ) Esse quadro decorre da falta de fiscalização e do consumo excessivo de plástico. ( ) No Brasil, entretanto, o acúmulo de lixo em rios e mares ainda ameaça esse direito. ( ) O artigo 225 da Constituição garante a todos o direito ao meio ambiente ecologicamente equilibrado.', '3 – 2 – 1 (o artigo 225 contextualiza; a segunda frase apresenta a tese; a primeira anuncia os argumentos).'),
     A('Complete com as palavras do quadro: “____ a Declaração Universal dos Direitos Humanos, todos nascem livres e iguais em dignidade e direitos. No Brasil, ____, a intolerância religiosa ainda desrespeita esse princípio. Esse problema ____ da falta de conhecimento sobre as diferentes religiões ____ da omissão diante dos ataques.”', 'Segundo; entretanto; decorre; e.', 2, banco=['Segundo', 'entretanto', 'decorre', 'e', 'portanto', 'porque']),
     A('Escreva uma frase de contextualização com repertório para o tema “Manipulação do comportamento do usuário pelo controle de dados na internet” (2018).', 'Resposta pessoal. Ex.: O documentário “O Dilema das Redes” (2020) revela como os algoritmos das redes sociais são criados para prender a atenção e influenciar o comportamento dos usuários.', 2),
     A('A introdução abaixo não tem tese. Reescreva-a, acrescentando um ponto de vista: “O cinema surgiu no fim do século XIX. Hoje existem muitos filmes no Brasil.”', 'Resposta pessoal. Ex.: Surgido no fim do século XIX, o cinema tornou-se uma importante forma de arte e de reflexão. No Brasil, entretanto, o acesso às salas de cinema ainda é desigual, o que exclui grande parte da população dessa experiência cultural.', 3),
  ],
  producao='Escreva a introdução (4 a 6 linhas) de uma redação sobre o tema “Desafios para a garantia da mobilidade urbana nas periferias brasileiras” (ou outro tema indicado pelo professor), seguindo as 3 partes: contextualização com repertório, tema e tese, anúncio de dois argumentos. Depois, sublinhe a tese e numere os argumentos (1 e 2).')

E(65, B, 'Introdução II: estratégias de abertura (alusão histórica, citação, dado, definição e pergunta)',
  aquecimento='Desafio relâmpago: em 2 minutos, cada dupla cria a primeira frase mais interessante possível para um texto sobre o uso do celular na escola. A turma vota na que mais prende a atenção.',
  quadro=['# A primeira frase da introdução',
    '- A abertura (contextualização) prende a atenção do leitor e conduz ao tema. Escolha a estratégia que combina com o repertório que você tem.',
    '# Um tema, várias aberturas (tema: o estigma associado às doenças mentais na sociedade brasileira, ENEM 2020)',
    '- Alusão histórica: Durante boa parte do século XX, pessoas com transtornos mentais foram isoladas em hospícios, longe da família e da sociedade.',
    '- Citação: Para o filósofo Byung-Chul Han, vivemos uma “sociedade do cansaço”, em que a cobrança por desempenho adoece as pessoas.',
    '- Dado: A Organização Mundial da Saúde aponta a depressão como uma das principais causas de incapacidade no mundo.',
    '- Definição: Estigma é uma marca negativa atribuída a pessoas ou grupos, que passam a ser vistos com preconceito.',
    '- Pergunta: Por que tantas pessoas ainda sentem vergonha de procurar ajuda psicológica? (A tese deve responder logo em seguida.)',
    '- Comparação: Assim como uma fratura exige cuidados médicos, a depressão também exige tratamento; porém, só as doenças do corpo costumam ser levadas a sério.',
    '- Fato social: Nos últimos anos, o debate sobre ansiedade e depressão ganhou espaço nas escolas, nas empresas e nas redes sociais.',
    '- Alusão literária: No conto “O Alienista”, de Machado de Assis, o médico Simão Bacamarte interna quase toda a cidade no hospício, em nome da ciência.',
    '# Como continuar depois da abertura',
    '- Ligue a abertura ao tema com um conectivo: “No Brasil, entretanto,…”, “Essa realidade…”, “Nesse contexto,…”.',
    '- Em seguida, apresente a tese e anuncie os dois argumentos (modelo do encontro anterior).',
    '# Cuidados com cada estratégia',
    '- Pergunta retórica: nunca a deixe sem resposta, pois a tese deve respondê-la. Evite várias perguntas seguidas ou dirigidas ao leitor (“E você?”).',
    '- Citação: só cite aquilo de que você tem certeza. Citação inventada ou atribuída ao autor errado tira a credibilidade do texto.',
    '- Dado: não invente números. Se não lembrar o valor exato, use uma informação geral e verdadeira (“pesquisas apontam que…”).',
    '- Definição: defina um conceito importante para o tema, e não uma palavra óbvia (“A escola é um lugar onde se estuda”).',
    '# Fique atento',
    '- Toda abertura precisa ter relação direta com o tema: uma frase bonita, mas desconectada, não ajuda.',
    '- Tenha repertórios de áreas diferentes (história, filosofia, leis, literatura, cinema) para variar as aberturas.',
    '- A abertura ocupa de 1 a 2 linhas: não transforme a introdução em uma aula de história.'],
  q=[M('Que estratégia de abertura é usada em: “Em 1888, a Lei Áurea aboliu a escravidão, mas não garantiu terra, emprego nem educação aos libertos.”?', ['alusão histórica', 'pergunta retórica', 'definição', 'comparação'], 0),
     M('“Racismo estrutural é aquele que está presente nas instituições, na economia e na política, e não apenas em atitudes individuais.” Essa abertura usa:', ['definição', 'alusão histórica', 'dado estatístico', 'pergunta retórica'], 0),
     M('Qual abertura é uma comparação?', ['Assim como uma planta precisa de água, uma democracia precisa de cidadãos bem informados.', 'Em 1932, as mulheres conquistaram o direito de votar no Brasil, depois de anos de luta.', 'Por que as notícias falsas se espalham tão depressa pelas redes sociais do país?', 'Segundo Aristóteles, o ser humano é um “animal político”, que vive em sociedade.'], 0),
     T('Tema: “Desafios para a formação de leitores no Brasil”. '
       'Abertura 1: O escritor Monteiro Lobato afirmou que “um país se faz com homens e livros”. '
       'Abertura 2: Em “Fahrenheit 451”, de Ray Bradbury, os livros são proibidos e queimados para impedir que as pessoas pensem de forma crítica. '
       'Abertura 3: Leitor é aquele que não apenas decifra palavras, mas compreende, interpreta e questiona o que lê. '
       'Abertura 4: O que leva tantos jovens a abandonar a leitura assim que deixam a escola? '
       'Abertura 5: Assim como o corpo precisa de exercício para se fortalecer, a mente precisa da leitura para se desenvolver.',
       fonte='Texto elaborado para esta atividade.', titulo='Cinco aberturas para um mesmo tema', para=4),
     C('Associe cada abertura à estratégia usada:', [('Abertura 1', 'citação'), ('Abertura 2', 'alusão a uma obra literária'), ('Abertura 3', 'definição'), ('Abertura 4', 'pergunta retórica'), ('Abertura 5', 'comparação')]),
     M('Para que a Abertura 4 funcione bem, o autor deve:', ['responder à pergunta logo em seguida, na tese', 'fazer outras perguntas seguidas para o leitor pensar', 'deixar a resposta para o leitor imaginar sozinho', 'repetir a mesma pergunta na conclusão, sem responder'], 0),
     M('Qual abertura cita um autor brasileiro?', ['Abertura 1', 'Abertura 2', 'Abertura 3', 'Abertura 5'], 0),
     A('Escolha uma das aberturas e continue a introdução: escreva a tese e anuncie dois argumentos.', 'Resposta pessoal. Ex.: (Abertura 1) No Brasil, entretanto, a formação de leitores ainda enfrenta obstáculos, o que limita o desenvolvimento crítico da população. Esse cenário decorre do acesso desigual a livros e bibliotecas e da falta de estímulo à leitura nas famílias e nas escolas.', 4),
     M('Um estudante escreveu: “Segundo Einstein, a internet é a maior invenção da humanidade.” Qual é o problema dessa abertura?', ['a citação é inventada: Einstein morreu em 1955, antes de a internet existir', 'a frase está escrita na 3ª pessoa do singular, e não na 1ª pessoa', 'citações de cientistas nunca podem ser usadas na redação do ENEM', 'a frase é curta demais para ser usada no início de uma introdução'], 0),
     M('Qual abertura usa um dado de forma segura, sem inventar números?', ['Pesquisas apontam que a população idosa cresce no Brasil.', 'Exatamente 87,3% dos idosos vivem sozinhos no Brasil.', 'Todos os idosos brasileiros sofrem algum tipo de abandono.', 'Metade da população do mundo já tem mais de 60 anos.'], 0),
     M('Qual é o problema da abertura: “Você já parou para pensar nisso? E se fosse com você? O que você faria?”', ['perguntas em excesso, dirigidas ao leitor e sem resposta', 'uso de um repertório histórico pouco conhecido', 'excesso de dados estatísticos sem indicação de fonte', 'falta de vírgulas entre as orações do período'], 0),
     M('A estratégia “contextualização por fato social” consiste em:', ['partir de um acontecimento ou situação atual ligada ao tema', 'contar uma história inventada, com personagens e diálogos', 'copiar a frase-tema da proposta, palavra por palavra', 'apresentar uma lista de números sem nenhuma explicação'], 0),
     VF('Marque V ou F sobre as estratégias de abertura:', [('Uma pergunta retórica deve ser respondida no próprio texto.', True), ('Se não lembrar um número exato, é melhor inventar um valor aproximado.', False), ('A abertura deve ter relação direta com o tema.', True), ('Definir uma palavra óbvia, como “escola”, é uma boa estratégia.', False), ('Fatos sociais atuais podem servir de contextualização.', True)]),
     A('Escreva uma abertura com alusão histórica para o tema “A persistência da violência contra a mulher na sociedade brasileira” (ENEM 2015).', 'Resposta pessoal. Ex.: Somente em 1932 as mulheres conquistaram o direito ao voto no Brasil, o que mostra como a igualdade de gênero tem sido construída lentamente no país.', 2),
     A('Transforme a afirmação em pergunta retórica e responda-a em seguida: “Muitos jovens não procuram ajuda psicológica por medo de julgamento.”', 'Ex.: Por que muitos jovens não procuram ajuda psicológica? Em grande parte, por medo do julgamento alheio, reflexo do estigma que ainda cerca as doenças mentais.', 2),
     A('Reescreva a abertura, corrigindo o problema: “O que é educação? Educação é uma coisa muito importante.”', 'Resposta pessoal. Ex.: Segundo o artigo 205 da Constituição, a educação é direito de todos e visa ao pleno desenvolvimento da pessoa e ao exercício da cidadania.', 2),
     A('Escreva duas aberturas diferentes para o tema “Democratização do acesso ao cinema no Brasil” e diga qual estratégia usou em cada uma.', 'Resposta pessoal. Ex.: Comparação: Assim como a escola, o cinema também educa, pois amplia a visão de mundo do espectador. Fato social: Nos últimos anos, as plataformas de streaming mudaram a forma como os brasileiros assistem a filmes.', 4),
  ],
  producao='Escolha um tema (o da sua redação ou “Desafios para a formação de leitores no Brasil”) e escreva três aberturas diferentes (por exemplo: alusão histórica, citação e pergunta). Depois, escolha a melhor e complete a introdução com a tese e o anúncio de dois argumentos (4 a 6 linhas).')

E(66, B, 'Desenvolvimento I: o parágrafo argumentativo (tópico frasal, fundamentação e fechamento)',
  aquecimento='Um voluntário defende oralmente, em 1 minuto, a ideia “a escola deveria ter mais aulas práticas”. A turma avalia: ele apresentou a ideia, deu razões e exemplos e concluiu?',
  quadro=['# O parágrafo de desenvolvimento',
    '- Cada parágrafo de desenvolvimento defende UM argumento anunciado na introdução.',
    '- Tamanho ideal: de 7 a 9 linhas. A redação tem dois desenvolvimentos (D1 e D2).',
    '# As 3 partes do parágrafo',
    '- 1) Tópico frasal: a primeira frase, que apresenta o argumento. Começa com um conectivo (Em primeiro lugar, Além disso, Ademais…).',
    '- 2) Fundamentação: explica o argumento (por quê? como?) e o comprova com repertório ou exemplo.',
    '- 3) Fechamento: conclui o parágrafo e liga o argumento à tese (Dessa forma, Assim, Logo…).',
    '# Exemplo de D1 (tema: caminhos para combater a intolerância religiosa no Brasil, ENEM 2016)',
    '- [Tópico frasal] Em primeiro lugar, a falta de conhecimento sobre as diferentes religiões alimenta o preconceito.',
    '- [Explicação] Quem não conhece as crenças do outro tende a vê-las com desconfiança, o que favorece estereótipos e ataques.',
    '- [Repertório] Essa realidade contraria a Constituição de 1988, que, no artigo 5º, declara inviolável a liberdade de consciência e de crença.',
    '- [Fechamento] Assim, a desinformação impede o respeito à diversidade religiosa e mantém viva a intolerância no país.',
    '# Conectivos para cada parte',
    '- Tópico frasal do D1: Em primeiro lugar, Primeiramente, Inicialmente, De início.',
    '- Tópico frasal do D2: Além disso, Ademais, Outrossim, Somado a isso, Paralelamente.',
    '- Explicação e exemplo: Isso ocorre porque, Por exemplo, Prova disso é, Nesse sentido, Segundo.',
    '- Fechamento: Dessa forma, Assim, Logo, Portanto, Desse modo.',
    '# Fique atento',
    '- O tópico frasal deve ser uma frase completa e clara: o leitor precisa entender o argumento só por ela.',
    '- Não coloque dois argumentos no mesmo parágrafo nem comece um assunto novo no fechamento.',
    '- Depois de citar um repertório, explique a relação dele com o argumento.',
    '- O D1 e o D2 devem desenvolver exatamente os argumentos anunciados na introdução, na mesma ordem.'],
  q=[M('Quais são as três partes do parágrafo de desenvolvimento?', ['tópico frasal, fundamentação e fechamento', 'contextualização, tese e anúncio', 'agente, ação e finalidade', 'título, resumo e assinatura'], 0),
     M('No modelo estudado, qual é a extensão ideal de um parágrafo de desenvolvimento?', ['de 7 a 9 linhas', 'de 1 a 2 linhas', 'de 3 a 4 linhas', 'de 15 a 20 linhas'], 0),
     M('Qual conectivo é mais adequado para iniciar o fechamento do parágrafo?', ['Dessa forma', 'Em primeiro lugar', 'Por exemplo', 'Ademais'], 0),
     M('Qual frase é um bom tópico frasal?', ['Em primeiro lugar, a precariedade do transporte coletivo dificulta o acesso dos moradores das periferias ao trabalho.', 'Ontem, no meu bairro, o ônibus atrasou mais de uma hora, e muita gente chegou atrasada ao serviço.', 'Assim, conclui-se que o governo deve investir mais no transporte público das grandes cidades.', 'O transporte coletivo existe há muitos anos na maioria das cidades do Brasil e do mundo.'], 0),
     T('Além disso, a falta de reconhecimento dos saberes tradicionais contribui para a desvalorização desses povos. Isso ocorre porque parte da sociedade considera “atrasados” os conhecimentos de indígenas, quilombolas e ribeirinhos, como o manejo sustentável da floresta e o uso de plantas medicinais. Nesse sentido, o líder indígena e escritor Ailton Krenak, em “Ideias para adiar o fim do mundo”, critica a separação entre ser humano e natureza e mostra que os povos originários vivem de outra forma com a Terra. Desse modo, ignorar esses saberes significa desperdiçar soluções para a crise ambiental e manter essas comunidades à margem.',
       fonte='Texto elaborado para esta atividade.', titulo='Desenvolvimento de uma redação (tema do ENEM 2022)', para=4),
     A('Copie o tópico frasal do parágrafo.', '“Além disso, a falta de reconhecimento dos saberes tradicionais contribui para a desvalorização desses povos.”', 2),
     M('O conectivo “Além disso”, no início do parágrafo, indica que ele é:', ['o segundo desenvolvimento, que acrescenta um novo argumento', 'a introdução da redação, que apresenta o tema ao leitor', 'a conclusão, que apresenta a proposta de intervenção', 'um parágrafo que contradiz o argumento anterior'], 0),
     M('Qual repertório é usado na fundamentação?', ['o livro “Ideias para adiar o fim do mundo”, de Ailton Krenak', 'o artigo 5º da Constituição Federal de 1988', 'o filme “Bacurau”, sobre uma comunidade do sertão', 'a Declaração Universal dos Direitos Humanos, de 1948'], 0),
     A('Copie o fechamento e explique como ele se liga à tese.', 'Fechamento: “Desse modo, ignorar esses saberes significa desperdiçar soluções para a crise ambiental e manter essas comunidades à margem.” Ele mostra a consequência do argumento e o liga à tese: a desvalorização dos povos tradicionais.', 3),
     M('Qual conectivo é adequado para iniciar o tópico frasal do D2?', ['Ademais', 'Em suma', 'Portanto', 'Em primeiro lugar'], 0),
     M('No exemplo do quadro, a frase sobre o artigo 5º da Constituição faz parte da:', ['fundamentação, com repertório', 'introdução, com a tese', 'conclusão, com a proposta', 'contextualização do tema'], 0),
     M('Na fundamentação, depois de citar um repertório, o autor deve:', ['explicar a relação entre o repertório e o argumento', 'passar logo para o parágrafo seguinte, sem comentar', 'citar outro repertório, sem explicar nenhum deles', 'apresentar a proposta de intervenção completa'], 0),
     VF('Marque V ou F sobre o parágrafo de desenvolvimento:', [('Cada desenvolvimento deve defender um argumento anunciado na introdução.', True), ('É bom colocar três ou quatro argumentos diferentes no mesmo parágrafo.', False), ('O fechamento liga o argumento à tese.', True), ('O tópico frasal deve ficar no fim do parágrafo.', False)]),
     A('Numere as frases na ordem correta para formar um parágrafo (1 a 4): ( ) Assim, o acesso desigual à internet amplia a desigualdade educacional. ( ) Em primeiro lugar, muitos estudantes de escolas públicas não têm acesso à internet em casa. ( ) Durante o ensino remoto, por exemplo, essa falta de recursos impediu muitos alunos de acompanhar as aulas. ( ) Isso ocorre porque o preço dos aparelhos e da conexão ainda é alto para muitas famílias.', '4 – 1 – 3 – 2 (ordem do parágrafo: tópico frasal, explicação, exemplo e fechamento).'),
     A('Complete o parágrafo com os conectivos do quadro: “____, as redes sociais favorecem a disseminação de notícias falsas. ____ os algoritmos mostram ao usuário conteúdos que confirmam suas opiniões. ____, o documentário “O Dilema das Redes” revela como essas plataformas são criadas para prender a atenção. ____, a desinformação se espalha com rapidez.”', 'Em primeiro lugar; Isso ocorre porque; Nesse sentido; Dessa forma.', 2, banco=['Em primeiro lugar', 'Isso ocorre porque', 'Nesse sentido', 'Dessa forma', 'Ainda que', 'Embora']),
     A('Escreva um tópico frasal para o argumento “o preconceito contra pessoas com deficiência no mercado de trabalho”.', 'Resposta pessoal. Ex.: Além disso, o preconceito ainda afasta as pessoas com deficiência do mercado de trabalho.', 2),
     A('Escreva um fechamento para este parágrafo: “Em primeiro lugar, o consumo excessivo de produtos descartáveis aumenta a produção de lixo. Isso ocorre porque muitas pessoas valorizam a praticidade e trocam objetos com frequência. A animação “Wall-E”, por exemplo, imagina um planeta coberto de lixo, consequência do consumismo.”', 'Resposta pessoal. Ex.: Dessa forma, o consumismo agrava o acúmulo de lixo e ameaça o equilíbrio do meio ambiente.', 2),
  ],
  producao='Escreva o primeiro parágrafo de desenvolvimento (D1) da sua redação, de 7 a 9 linhas, sobre o primeiro argumento que você anunciou na introdução (encontro 64) ou sobre o tema “Desafios para a garantia da mobilidade urbana nas periferias brasileiras”. Inclua tópico frasal com conectivo, explicação, repertório ou exemplo e fechamento ligado à tese. Marque cada parte com colchetes.')

E(67, B, 'Desenvolvimento II: aprofundar o argumento (explicar, exemplificar e relacionar ao tema)',
  aquecimento='O professor diz uma afirmação (“Os jovens leem pouco”) e a turma pergunta, em cadeia, “Por quê?” e “E daí?” até chegar a uma explicação e a uma consequência.',
  quadro=['# Parágrafo raso x parágrafo aprofundado',
    '- Raso: afirma, mas não explica nem comprova. Ex.: “O racismo é um problema. Ele é muito ruim e deve acabar.”',
    '- Aprofundado: apresenta o argumento, explica a causa, comprova com repertório ou exemplo e mostra a consequência.',
    '# A técnica “o quê? por quê? e daí?”',
    '- O quê? Qual é o argumento? (tópico frasal)',
    '- Por quê? Por que isso acontece? Como? (explicação + repertório ou exemplo)',
    '- E daí? Qual é a consequência? Como isso se relaciona com o tema e com a tese? (fechamento)',
    '# Exemplo (tema: desafios para a valorização da herança africana no Brasil, ENEM 2024)',
    '- O quê? O racismo herdado da escravidão ainda desvaloriza as contribuições africanas na cultura brasileira.',
    '- Por quê? A Lei Áurea (1888) aboliu a escravidão sem garantir terra, emprego ou educação aos libertos, o que manteve a população negra à margem da sociedade.',
    '- E daí? Por isso, manifestações de origem africana, como as religiões afro-brasileiras, ainda são alvo de preconceito, o que dificulta a valorização dessa herança.',
    '# Como aprofundar',
    '- Explique as causas: “Isso ocorre porque…”, “Tal fato se deve a…”.',
    '- Dê exemplos concretos: “Prova disso é…”, “Por exemplo,…”, “É o caso de…”.',
    '- Mostre consequências: “Como consequência,…”, “Isso faz com que…”, “Desse modo,…”.',
    '- Relacione ao tema: retome as palavras-chave do tema no fechamento do parágrafo.',
    '# Fique atento',
    '- Achismo: opinião sem argumento (“Eu acho que…”, “Todo mundo sabe que…”). Troque por explicação e prova.',
    '- Lista de informações: citar leis, filmes e dados um atrás do outro, sem análise, não aprofunda o argumento.',
    '- Generalizações: evite “todos”, “ninguém”, “sempre”, “nunca”; prefira “muitos”, “parte da população”, “frequentemente”.',
    '- Um repertório bem explicado vale mais do que três repertórios apenas citados.'],
  q=[M('Na técnica “o quê? por quê? e daí?”, a pergunta “por quê?” corresponde:', ['à explicação das causas, com repertório ou exemplo', 'à apresentação do tema na introdução do texto', 'à proposta de intervenção, feita na conclusão', 'à escolha de um título criativo para o texto'], 0),
     M('Qual frase é um exemplo de achismo?', ['Eu acho que as pessoas deveriam reciclar mais, e pronto.', 'A reciclagem reduz a quantidade de lixo enviada aos aterros.', 'A Política Nacional de Resíduos Sólidos, de 2010, incentiva a reciclagem.', 'Isso ocorre porque falta coleta seletiva em muitos municípios.'], 0),
     M('Qual expressão introduz uma CONSEQUÊNCIA?', ['Como consequência,', 'Isso ocorre porque', 'Por exemplo,', 'Em primeiro lugar,'], 0),
     T('Parágrafo 1: O trabalho infantil é um problema muito grave no Brasil. Eu acho que isso é um absurdo, porque toda criança deveria estar na escola. Todo mundo sabe que é errado. Existe o ECA, existe a Constituição e existem várias leis. Por isso, o trabalho infantil tem que acabar logo. '
       'Parágrafo 2: Em primeiro lugar, a pobreza de muitas famílias favorece a persistência do trabalho infantil. Isso ocorre porque, sem renda suficiente, pais e responsáveis acabam contando com o trabalho dos filhos para o sustento da casa. Essa realidade contraria o Estatuto da Criança e do Adolescente, que garante proteção integral e prioridade absoluta a crianças e adolescentes. Como consequência, muitos jovens abandonam a escola, o que limita suas oportunidades futuras e perpetua o ciclo de pobreza.',
       fonte='Textos elaborados para esta atividade.', titulo='Dois parágrafos sobre o trabalho infantil', para=4),
     M('O Parágrafo 1 é considerado raso porque:', ['faz afirmações e cita leis sem explicar nem relacioná-las ao argumento', 'usa a 3ª pessoa, a norma-padrão e conectivos bem variados', 'tem tópico frasal, explicação, exemplo e fechamento ligado à tese', 'apresenta um único repertório, bem explicado e produtivo'], 0),
     A('Copie do Parágrafo 1 duas marcas de achismo ou de generalização.', '“Eu acho que isso é um absurdo” e “Todo mundo sabe que é errado”.', 2),
     M('No Parágrafo 2, a frase “Como consequência, muitos jovens abandonam a escola…” responde a qual pergunta da técnica?', ['E daí?', 'O quê?', 'Por quê?', 'Quem?'], 0),
     A('O Parágrafo 1 cita “o ECA” e “a Constituição” em forma de lista. Como o Parágrafo 2 usa o ECA de modo produtivo?', 'Ele explica o que o ECA garante (proteção integral e prioridade absoluta a crianças e adolescentes) e mostra que o trabalho infantil contraria essa garantia, ligando a lei ao argumento.', 3),
     M('Qual trecho é uma generalização que deve ser evitada?', ['Ninguém se importa com o meio ambiente.', 'Parte da população ainda descarta lixo de forma irregular.', 'Muitos municípios ainda não têm coleta seletiva.', 'O descarte irregular agrava as enchentes em algumas cidades.'], 0),
     M('O que caracteriza uma “lista de informações sem análise”?', ['citar vários repertórios seguidos sem explicar a relação deles com o argumento', 'explicar um único repertório de forma detalhada e ligada ao argumento', 'usar conectivos de causa e de consequência para encadear as ideias', 'retomar as palavras-chave do tema no fechamento do parágrafo'], 0),
     M('“Como consequência, muitos idosos ficam isolados e adoecem.” Essa frase aprofunda o argumento porque:', ['mostra o efeito do problema', 'apresenta uma definição', 'faz uma pergunta ao leitor', 'cita uma lei importante'], 0),
     M('Qual alternativa traz um EXEMPLO concreto que aprofunda o argumento “o transporte público é precário nas periferias”?', ['Em muitos bairros afastados, os moradores esperam muito tempo pelo ônibus e viajam em veículos lotados.', 'O transporte público é um assunto muito importante, que merece a atenção de toda a sociedade brasileira.', 'Todo mundo odeia andar de ônibus, porque o transporte público no Brasil é sempre horrível.', 'Ônibus, metrô e trem são exemplos de meios de transporte público usados nas cidades.'], 0),
     VF('Marque V ou F sobre o aprofundamento do argumento:', [('Um bom parágrafo explica por que o argumento é verdadeiro.', True), ('Quanto mais repertórios citados sem explicação, melhor o parágrafo.', False), ('O fechamento deve relacionar o argumento ao tema.', True), ('“Todo mundo sabe que…” é um argumento forte.', False), ('Exemplos concretos ajudam a comprovar o argumento.', True)]),
     A('Transforme o achismo em argumento: “Eu acho que as redes sociais fazem mal para os jovens.”', 'Ex.: O uso excessivo das redes sociais pode prejudicar a saúde mental dos jovens, uma vez que a comparação constante com padrões irreais favorece a ansiedade e a baixa autoestima.', 2),
     A('Complete com as expressões do quadro: “Muitas pessoas ainda deixam de se vacinar. ____ circulam notícias falsas sobre os efeitos das vacinas. ____ disso é a queda da cobertura vacinal contra algumas doenças nos últimos anos. ____, doenças antes controladas podem voltar a se espalhar.”', 'Isso ocorre porque; Prova; Como consequência.', 2, banco=['Isso ocorre porque', 'Prova', 'Como consequência', 'Embora', 'Ao contrário']),
     A('Responda às perguntas da técnica para o argumento “a falta de acessibilidade nas cidades”: O quê? Por quê? E daí?', 'Resposta pessoal. Ex.: O quê? A falta de acessibilidade nas cidades exclui pessoas com deficiência. Por quê? Calçadas irregulares, ônibus sem elevador e prédios sem rampa dificultam a locomoção, apesar da Lei Brasileira de Inclusão (2015). E daí? Essas pessoas têm dificuldade para estudar, trabalhar e exercer a cidadania.', 3),
     A('Reescreva o parágrafo fraco, aprofundando-o com explicação, exemplo ou repertório e consequência: “A violência nas escolas é um problema. Isso é muito ruim. Todo mundo sabe que bullying é errado. Tem que acabar.”', 'Resposta pessoal. Ex.: Em primeiro lugar, o bullying contribui para a violência nas escolas. Isso ocorre porque agressões repetidas, muitas vezes vistas como “brincadeira”, são naturalizadas pelos colegas. Embora a Lei 13.185/2015 tenha instituído o Programa de Combate à Intimidação Sistemática, muitas escolas ainda não desenvolvem ações de prevenção. Como consequência, as vítimas sofrem com ansiedade, isolamento e queda no desempenho escolar.', 4),
  ],
  producao='Escreva o segundo parágrafo de desenvolvimento (D2) da sua redação, de 7 a 9 linhas, usando a técnica “o quê? por quê? e daí?”: apresente o argumento, explique a causa, comprove com repertório ou exemplo e mostre a consequência ligada ao tema. Evite achismos, generalizações e listas de informações sem análise.')

E(68, B, 'Competência 4: coesão na redação (conectivos e referenciação)',
  aquecimento='Jogo do conectivo: o professor fala o começo de uma frase com um conectivo (“Choveu muito, portanto…”; “Choveu muito, embora…”) e os alunos completam oralmente, respeitando o sentido.',
  quadro=['# O que a Competência 4 avalia',
    '- Os mecanismos que ligam as partes do texto: conectivos (entre os parágrafos e dentro deles) e referenciação (retomar sem repetir).',
    '- Um texto coeso é fácil de seguir: o leitor percebe a relação entre as ideias (adição, oposição, causa, conclusão…).',
    '# Conectivos entre os parágrafos',
    '- D1: Em primeiro lugar, Primeiramente, De início.',
    '- D2: Além disso, Ademais, Outrossim, Somado a isso.',
    '- Conclusão: Portanto, Dessa forma, Em suma, Diante do exposto.',
    '# Conectivos dentro dos parágrafos (relações de sentido)',
    '- Adição: e, também, além disso. Oposição: mas, porém, contudo, no entanto. Concessão: embora, ainda que, apesar de.',
    '- Causa: porque, já que, visto que, uma vez que. Conclusão: portanto, logo, por isso. Finalidade: para que, a fim de.',
    '- Exemplificação: por exemplo, como, a exemplo de. Explicação: isto é, ou seja. Consequência: de modo que, de forma que.',
    '# Referenciação: retomar sem repetir',
    '- Pronomes: “A internet ampliou o acesso à informação; ela, porém, também espalha boatos.” (ela = a internet)',
    '- Sinônimos e expressões equivalentes: idosos → pessoas idosas, população com 60 anos ou mais, esse grupo.',
    '- Termos que resumem uma ideia: “esse problema”, “tal cenário”, “essa realidade”, “essa situação”.',
    '- No tema de 2021 (registro civil), por exemplo: registro civil → certidão de nascimento, documentação; invisibilidade → exclusão.',
    '# Erros de coesão',
    '- Conectivo com sentido trocado: “Ele estudou muito, portanto não passou.” (o certo é “mas” ou “porém”).',
    '- Excesso de conectivos: “Portanto, logo, assim, conclui-se que…”. Use um só, o adequado.',
    '- “Onde” como coringa: “O ECA é uma lei onde…” → “O ECA é uma lei que…” ou “na qual…”.',
    '- Repetição de “que”: “É necessário que o governo crie leis que garantam que…”. Varie a construção.',
    '# Fique atento',
    '- Varie os conectivos: não comece todos os parágrafos do mesmo jeito nem repita “também” e “porque” o tempo todo.',
    '- Antes de usar um conectivo, pergunte: qual é a relação de sentido entre essas ideias?',
    '- O pronome deve deixar claro a que termo se refere; se houver dúvida, repita o nome ou use um sinônimo.'],
  q=[M('Qual conectivo indica OPOSIÇÃO?', ['no entanto', 'além disso', 'visto que', 'a fim de'], 0),
     M('Qual conectivo é adequado para iniciar a conclusão?', ['Diante do exposto', 'Em primeiro lugar', 'Por exemplo', 'Outrossim'], 0),
     M('Em qual frase o conectivo está com sentido trocado?', ['Muitos jovens querem estudar, portanto não encontram vagas nas universidades.', 'Muitos jovens querem estudar, mas não encontram vagas nas universidades.', 'Embora queiram estudar, muitos jovens não encontram vagas nas universidades.', 'Muitos jovens não continuam os estudos porque precisam trabalhar.'], 0),
     T('(1) A Lei Maria da Penha, de 2006, criou mecanismos para coibir a violência doméstica e familiar contra a mulher. Apesar desse avanço, essa forma de violência persiste no Brasil, devido à cultura machista e ao medo de denunciar. '
       '(2) Em primeiro lugar, o machismo ainda naturaliza o controle masculino sobre a mulher. Tal visão faz com que agressões sejam tratadas como “briga de casal”, e não como crime. '
       '(3) Além disso, muitas vítimas não denunciam o agressor, pois dependem financeiramente dele ou temem novas agressões. '
       '(4) Portanto, é necessário que o poder público, em parceria com escolas e meios de comunicação, promova campanhas sobre igualdade de gênero e sobre os canais de denúncia, a fim de romper o ciclo da violência.',
       fonte='Texto elaborado para esta atividade (redação em miniatura).', titulo='Violência contra a mulher (tema do ENEM 2015)', para=4),
     M('No parágrafo (1), a expressão “Apesar desse avanço” estabelece relação de:', ['concessão', 'conclusão', 'adição', 'finalidade'], 0),
     M('No parágrafo (2), a expressão “Tal visão” retoma:', ['a ideia de que o machismo naturaliza o controle masculino sobre a mulher', 'a Lei Maria da Penha, citada no início da introdução', 'as campanhas de conscientização propostas na conclusão', 'o medo que muitas vítimas têm de denunciar o agressor'], 0),
     M('No parágrafo (3), o conectivo “pois” introduz:', ['a causa de muitas vítimas não denunciarem', 'a conclusão de toda a redação', 'uma oposição ao parágrafo anterior', 'a finalidade da proposta de intervenção'], 0),
     A('Copie os conectivos que iniciam os parágrafos (2), (3) e (4) e diga a função de cada um.', '“Em primeiro lugar” (introduz o primeiro argumento), “Além disso” (acrescenta o segundo argumento) e “Portanto” (introduz a conclusão).', 2),
     M('Leia: “Os idosos precisam de atenção. ____ ainda sofrem com o abandono.” Qual expressão retoma “Os idosos” sem repetir a palavra?', ['Essas pessoas', 'Esses jovens', 'Tais crianças', 'Essas leis'], 0),
     M('Como fica a frase “Vivemos um momento onde a aparência é supervalorizada” na norma-padrão?', ['Vivemos um momento em que a aparência é supervalorizada.', 'Vivemos um momento aonde a aparência é supervalorizada.', 'Vivemos um momento cujo a aparência é supervalorizada.', 'Vivemos um momento o qual a aparência é supervalorizada.'], 0),
     M('Qual alternativa evita a repetição excessiva de “que”?', ['É necessário que o governo crie leis capazes de garantir a inclusão.', 'É necessário que o governo crie leis que garantam que haja inclusão.', 'É preciso que se faça com que o governo crie leis que garantam a inclusão.', 'É necessário que o governo faça que as leis que existem garantam a inclusão.'], 0),
     VF('Marque V ou F sobre coesão:', [('Usar o mesmo conectivo em todos os parágrafos deixa o texto mais coeso.', False), ('“Tal cenário” e “essa realidade” podem retomar ideias já apresentadas.', True), ('“Embora” introduz uma ideia de concessão.', True), ('Quanto mais conectivos numa mesma frase, melhor.', False), ('Pronomes como “ele” e “ela” podem evitar repetições.', True)]),
     C('Associe o conectivo à relação de sentido que ele expressa:', [('visto que', 'causa'), ('ainda que', 'concessão'), ('a fim de', 'finalidade'), ('logo', 'conclusão'), ('ou seja', 'explicação')]),
     A('Reescreva evitando a repetição de “a internet”: “A internet facilita a comunicação. A internet também espalha notícias falsas. Por isso, a internet exige uso consciente.”', 'Ex.: A internet facilita a comunicação. Essa ferramenta, porém, também espalha notícias falsas; por isso, a rede exige uso consciente.', 2),
     A('Una as frases com um conectivo de oposição: “O Brasil tem leis de proteção ambiental. O desmatamento continua.”', 'Ex.: O Brasil tem leis de proteção ambiental, mas (porém, contudo, no entanto) o desmatamento continua.', 2),
     A('Corrija o excesso de conectivos: “Portanto, logo, assim, conclui-se que a educação é a solução.”', 'Ex.: Portanto, a educação é a solução. (ou: Conclui-se, assim, que a educação é a solução.)'),
     A('Para o tema “Democratização do acesso ao cinema no Brasil”, escreva um sinônimo ou expressão que possa retomar cada palavra: democratização – acesso – cinema – Brasil.', 'Ex.: democratização → ampliação, universalização; acesso → entrada, alcance; cinema → sétima arte, salas de exibição; Brasil → país, território nacional.', 2),
  ],
  producao='Revise a introdução e os dois desenvolvimentos que você escreveu nos encontros anteriores: circule os conectivos, troque os repetidos ou inadequados e substitua as repetições das palavras do tema por pronomes, sinônimos ou expressões como “esse problema”. Depois, passe a limpo o parágrafo que mais mudou (7 a 9 linhas).')

E(69, B, 'Conclusão e proposta de intervenção: os 5 elementos',
  aquecimento='Se vocês fossem resolver um problema da escola (por exemplo, o lixo no pátio), quem faria o quê, como e para quê? A turma monta a solução em voz alta.',
  quadro=['# O que vai na conclusão',
    '- Retomada da tese: relembre, com outras palavras, o problema e os argumentos discutidos.',
    '- Proposta de intervenção: uma solução concreta e detalhada para o problema (avaliada na Competência 5).',
    '- Tamanho ideal: de 5 a 8 linhas. Conectivos: Portanto, Dessa forma, Em suma, Diante do exposto.',
    '# Os 5 elementos da proposta',
    '- Agente (quem vai fazer?): Ministério da Educação, escolas, mídia, ONGs, famílias…',
    '- Ação (o que vai ser feito?): criar, ampliar, promover, fiscalizar, investir…',
    '- Meio/modo (como? por meio de quê?): por meio de campanhas, parcerias, palestras, aplicativos, verbas…',
    '- Finalidade/efeito (para quê?): a fim de, para que, com o objetivo de, de modo a…',
    '- Detalhamento: uma informação a mais sobre um dos elementos (quem é o agente, como funciona o meio, o que a ação inclui).',
    '# Exemplo (tema: desafios para a formação educacional de surdos no Brasil, ENEM 2017)',
    '- [Retomada] Portanto, a falta de professores bilíngues e o preconceito ainda dificultam a formação educacional dos surdos.',
    '- [Agente] Cabe ao Ministério da Educação, [Detalhamento] órgão responsável pela política educacional do país,',
    '- [Ação] ampliar a formação de professores em Libras, [Meio] por meio de cursos gratuitos e de verbas destinadas às escolas públicas,',
    '- [Finalidade] a fim de garantir que os estudantes surdos aprendam em sua língua e tenham as mesmas oportunidades dos ouvintes.',
    '# Proposta ligada ao texto',
    '- A proposta deve resolver os problemas discutidos nos desenvolvimentos: se o D1 tratou do preconceito e o D2 da falta de estrutura, a solução precisa atacar isso.',
    '- Você pode fazer uma proposta para cada argumento; capriche para que elas tenham os 5 elementos.',
    '# Direitos humanos',
    '- A proposta deve respeitar os direitos humanos: nada de violência, tortura, pena de morte, censura ou “justiça com as próprias mãos”.',
    '- Proposta que fere os direitos humanos é penalizada na Competência 5.',
    '# Fique atento',
    '- Não comece ideias novas na conclusão: ela fecha o que foi discutido.',
    '- Evite propostas vagas (“o governo deve fazer algo”, “as pessoas precisam se conscientizar”): diga quem, o quê, como e para quê.',
    '- Uma frase de efeito no final (“Só assim teremos um país melhor”) não substitui a proposta.'],
  q=[M('Quais são os 5 elementos da proposta de intervenção?', ['agente, ação, meio/modo, finalidade e detalhamento', 'introdução, tese, argumento, repertório e conclusão', 'sujeito, verbo, objeto, adjunto e aposto', 'tema, título, data, nome e assinatura'], 0),
     M('Na proposta “O Ministério da Saúde deve criar campanhas de vacinação nas escolas…”, o agente é:', ['o Ministério da Saúde', 'criar campanhas', 'as escolas', 'a vacinação'], 0),
     M('Qual expressão introduz o MEIO/MODO da proposta?', ['por meio de', 'a fim de', 'cabe a', 'em suma'], 0),
     T('Diante do exposto, a falta de informação e as dificuldades de acesso aos cartórios mantêm milhares de brasileiros sem registro civil e, portanto, invisíveis para o Estado. Para mudar essa realidade, o Governo Federal, em parceria com os municípios, deve promover mutirões itinerantes de emissão de certidões de nascimento em comunidades rurais e periferias, por meio de unidades móveis e de campanhas na rádio e na televisão, a fim de garantir que todos os cidadãos tenham acesso a direitos básicos, como saúde, educação e programas sociais.',
       fonte='Texto elaborado para esta atividade.', titulo='Conclusão de uma redação (tema do ENEM 2021)', para=4),
     C('Associe cada elemento da proposta ao trecho do texto:', [('agente', 'o Governo Federal'), ('ação', 'promover mutirões itinerantes de emissão de certidões de nascimento'), ('meio/modo', 'por meio de unidades móveis e de campanhas na rádio e na televisão'), ('finalidade', 'a fim de garantir que todos os cidadãos tenham acesso a direitos básicos'), ('detalhamento', 'como saúde, educação e programas sociais')]),
     A('Copie o trecho que retoma a tese.', '“Diante do exposto, a falta de informação e as dificuldades de acesso aos cartórios mantêm milhares de brasileiros sem registro civil e, portanto, invisíveis para o Estado.”', 2),
     M('A proposta do texto respeita os direitos humanos porque:', ['amplia o acesso de todos à documentação e aos direitos', 'pune com violência quem ainda não tem documentos', 'proíbe pessoas sem registro de usar serviços públicos', 'obriga as famílias sem registro a pagar multas altas'], 0),
     M('No texto, que expressão introduz a finalidade da proposta?', ['a fim de', 'por meio de', 'em parceria com', 'Diante do exposto'], 0),
     M('Qual proposta respeita os direitos humanos?', ['ampliar centros de acolhimento e apoio psicológico às vítimas de violência', 'aplicar castigos físicos aos agressores em praça pública', 'permitir que a população faça justiça com as próprias mãos', 'censurar os jornais que noticiam casos de violência'], 0),
     M('Qual é o problema da conclusão: “Portanto, o governo deve fazer alguma coisa para resolver isso.”?', ['é vaga: não detalha a ação, o meio e a finalidade', 'fere os direitos humanos ao propor uma punição', 'tem elementos demais para uma única frase', 'não usa nenhum conectivo de conclusão'], 0),
     M('O detalhamento é:', ['uma informação a mais sobre um dos elementos da proposta', 'a repetição do tema com as mesmas palavras da proposta', 'o título da redação, escrito acima do primeiro parágrafo', 'uma pergunta feita ao leitor no fim da conclusão'], 0),
     M('Um texto discutiu, no D1, o preconceito contra surdos e, no D2, a falta de intérpretes nas escolas. Qual proposta está mais ligada a esses problemas?', ['formar intérpretes de Libras e promover campanhas contra o preconceito nas escolas', 'construir mais quadras esportivas e áreas de lazer nos bairros de todo o país', 'reduzir os impostos cobrados sobre a venda de aparelhos de celular', 'aumentar o número de linhas de ônibus que atendem as grandes cidades'], 0),
     VF('Marque V ou F sobre a conclusão:', [('A conclusão deve retomar a tese.', True), ('É bom apresentar um argumento novo na conclusão.', False), ('A finalidade responde à pergunta “para quê?”.', True), ('Uma proposta que defende a pena de morte é bem avaliada na Competência 5.', False)]),
     A('Identifique os elementos da proposta: “As escolas, com apoio das secretarias de educação, devem promover rodas de conversa sobre saúde mental, mediadas por psicólogos, para que os estudantes aprendam a reconhecer o problema e a buscar ajuda.”', 'Agente: as escolas; detalhamento: com apoio das secretarias de educação; ação: promover rodas de conversa sobre saúde mental; meio/modo: mediadas por psicólogos; finalidade: para que os estudantes aprendam a reconhecer o problema e a buscar ajuda.', 3),
     A('Complete a proposta com os elementos que faltam (tema: o abandono de animais nas cidades): “Cabe ____ (agente) ____ (ação), ____ (meio), a fim de ____ (finalidade).”', 'Resposta pessoal. Ex.: Cabe às prefeituras ampliar os programas de castração e adoção, por meio de parcerias com ONGs e clínicas veterinárias, a fim de reduzir o número de animais abandonados.', 3),
     A('Escreva um detalhamento para o agente desta proposta: “O Ministério da Saúde deve ampliar o atendimento psicológico no SUS, por meio da contratação de profissionais, a fim de reduzir o sofrimento de quem enfrenta transtornos mentais.”', 'Resposta pessoal. Ex.: O Ministério da Saúde, órgão responsável pelas políticas públicas de saúde no país, deve ampliar…', 2),
     A('Escreva uma frase de retomada da tese para uma redação sobre “Desafios para a valorização da herança africana no Brasil”.', 'Resposta pessoal. Ex.: Diante do exposto, o racismo herdado da escravidão e a pouca presença da cultura afro-brasileira nas escolas ainda impedem a valorização da herança africana no Brasil.', 2),
  ],
  producao='Escreva a conclusão da sua redação (5 a 8 linhas): retome a tese e apresente uma proposta de intervenção com os 5 elementos (agente, ação, meio/modo, finalidade e detalhamento), ligada aos problemas discutidos nos seus desenvolvimentos. Depois, identifique cada elemento entre colchetes.')

E(70, B, 'Proposta de intervenção na prática: agentes, ações e direitos humanos',
  aquecimento='Quem pode resolver? O professor fala um problema (buraco na rua, falta de vacina no posto, bullying na sala) e a turma diz quem tem o poder de resolvê-lo e o que essa instituição pode fazer.',
  quadro=['# Banco de agentes (quem?)',
    '- Ministério da Educação: currículo, formação de professores, materiais didáticos, programas para as escolas públicas.',
    '- Ministério da Saúde: campanhas de saúde, atendimento no SUS, prevenção de doenças.',
    '- Escolas: palestras, rodas de conversa, projetos, feiras e debates com a comunidade.',
    '- Mídia (TV, rádio, internet, influenciadores digitais): campanhas de conscientização e informação de qualidade.',
    '- ONGs e sociedade civil: projetos sociais, acolhimento, cursos, mutirões.',
    '- Famílias: diálogo, acompanhamento dos filhos, exemplo dentro de casa.',
    '- Empresas: contratação inclusiva, patrocínio de projetos, responsabilidade social e ambiental.',
    '- Poder Legislativo (Congresso Nacional, assembleias legislativas, câmaras municipais): criar ou alterar leis.',
    '# Ações concretas (o quê?)',
    '- Verbos de ação: criar, ampliar, promover, fiscalizar, investir, capacitar, incluir no currículo, oferecer, divulgar.',
    '- Troque o vago pelo concreto: “conscientizar” → “promover campanhas na TV e nas redes sociais sobre…”.',
    '# Meios e finalidades (como? para quê?)',
    '- Meios: por meio de campanhas, parcerias, fiscalização, políticas públicas, investimento de verbas, aplicativos, palestras.',
    '- Finalidades: “a fim de reduzir…”, “para que todos tenham acesso a…”, “com o objetivo de garantir…”, “de modo a diminuir…”.',
    '# Proposta vaga x proposta completa',
    '- Vaga: “O governo deve fazer algo para acabar com a evasão escolar.” (Quem? O quê? Como? Para quê?)',
    '- Completa: “O Ministério da Educação deve ampliar as bolsas de permanência para alunos de baixa renda, por meio de parcerias com os estados, a fim de reduzir a evasão escolar.”',
    '- Com detalhamento: “O Ministério da Educação, órgão responsável pelas políticas educacionais do país, deve ampliar…”.',
    '# Direitos humanos: o que NÃO pode',
    '- Tortura, pena de morte, castigos físicos, prisão sem julgamento, censura, “fazer justiça com as próprias mãos”.',
    '- Propostas que excluem ou humilham grupos (expulsar imigrantes, expor pessoas, isolar doentes à força) também ferem os direitos humanos.',
    '- Base: Declaração Universal dos Direitos Humanos (1948) e Constituição Federal de 1988 (art. 5º).',
    '# Fique atento',
    '- Escolha um agente que realmente possa fazer a ação: criar leis é papel do Legislativo; campanhas, de ministérios e da mídia.',
    '- Evite agentes genéricos (“todos”, “a sociedade”, “o governo”) sem especificar quem.',
    '- A proposta deve atacar as causas discutidas nos desenvolvimentos.'],
  q=[M('Qual agente pode CRIAR uma nova lei?', ['o Poder Legislativo', 'as famílias brasileiras', 'as escolas públicas', 'os meios de comunicação'], 0),
     M('Qual agente é o mais adequado para organizar uma campanha nacional de vacinação?', ['o Ministério da Saúde', 'o Poder Legislativo', 'as empresas de tecnologia', 'os clubes esportivos'], 0),
     M('Qual alternativa apresenta uma AÇÃO concreta?', ['oferecer cursos gratuitos de educação financeira nas escolas públicas', 'fazer alguma coisa pelo bem de todos os cidadãos do país', 'mudar a mentalidade das pessoas do mundo inteiro', 'acabar de uma vez por todas com esse grave problema'], 0),
     T('Tema: “Caminhos para combater o bullying nas escolas brasileiras”. '
       'Proposta 1: Para acabar com o bullying, as pessoas precisam se conscientizar e respeitar mais umas às outras. '
       'Proposta 2: As escolas, com apoio das secretarias de educação, devem criar programas permanentes de prevenção ao bullying, como prevê a Lei 13.185/2015, por meio de rodas de conversa mediadas por psicólogos e de canais de denúncia anônima, a fim de proteger as vítimas e promover a convivência respeitosa. '
       'Proposta 3: Os alunos que praticam bullying devem ser humilhados na frente de toda a escola, para sentirem o que as vítimas sentem.',
       fonte='Texto elaborado para esta atividade.', titulo='Três propostas para o mesmo tema', para=4),
     M('Qual proposta é completa, com agente, ação, meio e finalidade?', ['Proposta 2', 'Proposta 1', 'Proposta 3', 'Propostas 1 e 3'], 0),
     A('Por que a Proposta 1 é considerada vaga?', 'Porque não indica um agente específico, uma ação concreta, um meio e uma finalidade: “as pessoas precisam se conscientizar” não diz quem deve fazer o quê, como e para quê.', 2),
     M('A Proposta 3 não pode ser usada porque:', ['fere os direitos humanos ao propor humilhação pública', 'é longa demais para caber no parágrafo de conclusão', 'não apresenta nenhum conectivo entre as orações', 'cita uma lei sobre bullying que não existe'], 0),
     A('Na Proposta 2, qual trecho detalha o agente?', '“com apoio das secretarias de educação”.'),
     M('Qual proposta para combater a criminalidade NÃO pode ser usada na redação?', ['instituir a pena de morte para quem comete crimes violentos', 'ampliar o policiamento comunitário nos bairros mais violentos', 'investir em iluminação pública e câmeras em áreas de risco', 'criar programas de estudo e trabalho para pessoas presas'], 0),
     M('“…por meio de parcerias com universidades…” é um exemplo de:', ['meio/modo', 'agente', 'finalidade', 'retomada da tese'], 0),
     M('Qual alternativa apresenta uma FINALIDADE?', ['a fim de reduzir os acidentes de trânsito', 'por meio de operações educativas nas rodovias', 'o Departamento Estadual de Trânsito', 'ampliar a fiscalização nas estradas'], 0),
     M('Qual proposta usa um agente genérico, que deve ser evitado?', ['Todos devem fazer sua parte para acabar com a fome no país.', 'O Governo Federal deve ampliar a rede de restaurantes populares.', 'As prefeituras devem criar bancos de alimentos com as feiras livres.', 'Os supermercados devem doar alimentos próximos da data de validade.'], 0),
     VF('Marque V ou F sobre a proposta de intervenção:', [('Criar leis é uma ação típica do Poder Legislativo.', True), ('“A sociedade” é um agente bem específico e sempre recomendado.', False), ('Censurar a imprensa é uma proposta que fere os direitos humanos.', True), ('Campanhas, parcerias e fiscalização são exemplos de meios.', True), ('Fazer justiça com as próprias mãos é aceitável quando o crime é grave.', False)]),
     C('Associe o agente à ação mais adequada a ele:', [('Ministério da Educação', 'incluir o tema no currículo escolar'), ('Poder Legislativo', 'aprovar uma lei sobre o assunto'), ('mídia', 'divulgar campanhas de conscientização'), ('empresas', 'contratar pessoas com deficiência'), ('famílias', 'dialogar com os filhos e acompanhar sua rotina')]),
     A('Transforme a proposta vaga em completa: “O governo deve fazer algo contra a poluição dos rios.”', 'Resposta pessoal. Ex.: As prefeituras, com apoio dos governos estaduais, devem ampliar a fiscalização sobre o despejo de esgoto e de resíduos industriais, por meio de multas e de investimentos em saneamento básico, a fim de recuperar os rios e proteger a saúde da população.', 3),
     A('Reescreva a proposta para que ela respeite os direitos humanos: “Os pais que não mandam os filhos à escola devem ser presos imediatamente, sem julgamento.”', 'Resposta pessoal. Ex.: Os conselhos tutelares, em parceria com as escolas, devem acompanhar as famílias de alunos faltosos, por meio de visitas e da inclusão em programas sociais, a fim de garantir o direito das crianças à educação.', 3),
     A('Escreva uma finalidade para a proposta: “A mídia deve divulgar campanhas sobre os direitos da pessoa idosa, por meio de propagandas na TV e nas redes sociais, ____.”', 'Resposta pessoal. Ex.: a fim de combater o abandono e a violência contra os idosos e de informar a população sobre o Estatuto da Pessoa Idosa.', 2),
  ],
  producao='Monte duas propostas de intervenção completas (com os 5 elementos) para o tema “Caminhos para combater o bullying nas escolas brasileiras” ou para o tema da sua redação: uma com um agente do poder público e outra com um agente da sociedade (escola, família, mídia, ONG ou empresa). Sublinhe o agente, circule a ação e marque o meio e a finalidade.')

E(71, B, 'Planejamento da redação: chuva de ideias, mapa e roteiro',
  aquecimento='Quanto tempo dura a prova do primeiro dia do ENEM e quanto dele deveria ficar para a redação? Cada um dá um palpite, e o professor revela: são 5 horas e 30 minutos para tudo.',
  quadro=['# Por que planejar',
    '- Quem planeja não foge do tema, não repete ideias e escreve mais rápido. O planejamento é o “projeto de texto” avaliado na Competência 3.',
    '# Passo a passo',
    '- 1) Ler a proposta: textos motivadores e frase-tema; sublinhar as palavras-chave e transformar o tema em pergunta.',
    '- 2) Chuva de ideias: anotar tudo o que vier à cabeça (causas, consequências, exemplos, repertórios, soluções), sem censura.',
    '- 3) Escolher a tese: a resposta à pergunta do tema, em uma frase.',
    '- 4) Selecionar 2 argumentos (geralmente duas causas do problema) e um repertório para cada um.',
    '- 5) Pensar a proposta de intervenção ligada aos dois argumentos (agente, ação, meio, finalidade e detalhamento).',
    '- 6) Fazer o roteiro: uma ou duas linhas para cada parágrafo (introdução, D1, D2 e conclusão).',
    '- 7) Escrever o rascunho seguindo o roteiro. 8) Revisar e passar a limpo, a caneta preta, na folha de redação.',
    '# Mapa (roteiro) do tema: desafios para o combate à desinformação nas redes sociais',
    '- Introdução: Kant e a coragem de pensar por si mesmo + tese: a desinformação ameaça a democracia + anúncio: algoritmos e falta de educação midiática.',
    '- D1: algoritmos que priorizam conteúdos chamativos; repertório: o documentário “O Dilema das Redes” (2020).',
    '- D2: falta de educação midiática nas escolas; repertório: Paulo Freire e a educação crítica e libertadora.',
    '- Conclusão: Ministério da Educação + incluir a educação midiática no currículo + por meio de oficinas de checagem de notícias + a fim de formar leitores críticos.',
    '# Gestão do tempo na prova',
    '- No ENEM, a redação é feita no 1º dia, com as provas de Linguagens e de Ciências Humanas. Reserve cerca de 1 hora e 30 minutos para ela.',
    '- Sugestão: 15 a 20 min para ler e planejar; 40 a 50 min para o rascunho; 10 min para revisar; 20 min para passar a limpo.',
    '- Você pode começar pela redação ou fazê-la no meio da prova, mas nunca a deixe para os últimos minutos.',
    '# Fique atento',
    '- Não pule o planejamento: dez minutos de roteiro economizam muito tempo depois.',
    '- O rascunho não é corrigido: só vale o texto da folha de redação.',
    '- No fim, confira: o texto tem mais de 7 e no máximo 30 linhas, sem identificação fora do local permitido?'],
  q=[M('Qual é o primeiro passo do planejamento da redação?', ['ler a proposta e sublinhar as palavras-chave do tema', 'escrever a conclusão com a proposta de intervenção', 'passar o texto a limpo na folha de redação', 'escolher um título criativo para chamar a atenção'], 0),
     M('Na chuva de ideias, o estudante deve:', ['anotar livremente causas, consequências, exemplos, repertórios e soluções', 'escrever o texto completo, já na versão final, sem fazer rascunho', 'copiar os trechos mais importantes dos textos motivadores', 'escolher logo a primeira ideia e descartar o resto sem pensar'], 0),
     M('O roteiro (mapa) da redação serve para:', ['organizar o que vai em cada parágrafo antes de escrever', 'substituir o texto final na folha de redação', 'ser entregue no lugar da redação, se faltar tempo', 'contar quantas palavras o texto terá no final'], 0),
     T('Tema: “Desafios para a inclusão de pessoas com deficiência no mercado de trabalho brasileiro”. Ideias anotadas: '
       '(1) preconceito: muitas empresas acham que a pessoa com deficiência produz menos; '
       '(2) Lei Brasileira de Inclusão (2015), que garante acessibilidade; '
       '(3) falta de acessibilidade: prédios sem rampa, ônibus sem elevador, sites sem recursos para pessoas cegas; '
       '(4) baixa escolaridade causada pela exclusão na escola; '
       '(5) meu primo adora videogame; '
       '(6) programas de contratação inclusiva nas empresas; '
       '(7) fiscalização da reserva de vagas pelo Ministério do Trabalho e Emprego; '
       '(8) a Copa do Mundo de 2014 foi no Brasil.',
       fonte='Texto elaborado para esta atividade.', titulo='A chuva de ideias de uma estudante', para=4),
     M('Quais ideias da lista devem ser descartadas por não terem relação com o tema?', ['a do primo que adora videogame e a da Copa do Mundo de 2014', 'a do preconceito das empresas e a da falta de acessibilidade', 'a da Lei Brasileira de Inclusão e a da fiscalização das vagas', 'a da baixa escolaridade e a dos programas de contratação'], 0),
     A('Escreva uma tese possível para esse tema, em uma frase.', 'Ex.: O preconceito e a falta de acessibilidade ainda impedem a plena inclusão das pessoas com deficiência no mercado de trabalho brasileiro.', 2),
     A('Escolha dois argumentos da lista para os desenvolvimentos e indique um repertório para um deles.', 'Ex.: D1: o preconceito das empresas, que acham que a pessoa com deficiência produz menos; D2: a falta de acessibilidade em prédios, transportes e sites. Repertório: a Lei Brasileira de Inclusão (2015), que garante acessibilidade.', 3),
     M('Quais ideias da lista podem inspirar a proposta de intervenção?', ['os programas de contratação inclusiva e a fiscalização da reserva de vagas', 'o preconceito das empresas e a baixa escolaridade dos candidatos', 'a Copa do Mundo de 2014 e o primo que adora videogame', 'os prédios sem rampa e os ônibus sem elevador da cidade'], 0),
     M('Em qual etapa o estudante decide quais serão os dois argumentos do texto?', ['na seleção das ideias, depois da chuva de ideias', 'na hora de passar o texto a limpo', 'depois de escrever a conclusão', 'durante a correção feita pelo professor'], 0),
     M('No ENEM, a redação é feita:', ['no primeiro dia, junto com Linguagens e Ciências Humanas', 'no segundo dia, junto com Matemática e Ciências da Natureza', 'em um terceiro dia de prova, reservado só para ela', 'em casa, alguns dias antes das provas objetivas'], 0),
     M('Qual divisão de tempo é mais adequada para a redação na prova?', ['cerca de 20 min para planejar, 45 para o rascunho, 10 para revisar e 20 para passar a limpo', 'apenas 5 min para tudo, nos últimos minutos da prova, direto na folha definitiva', 'três horas só para o rascunho, sem tempo reservado para passar o texto a limpo', '10 min para escrever direto na folha definitiva, sem planejamento e sem revisão'], 0),
     M('A Competência 3 avalia principalmente:', ['o projeto de texto: a seleção e a organização dos argumentos', 'a caligrafia do participante e a limpeza da folha', 'a quantidade de repertórios citados, mesmo sem explicação', 'o uso de palavras difíceis e pouco conhecidas'], 0),
     VF('Marque V ou F sobre o planejamento:', [('O rascunho é corrigido e vale nota.', False), ('A tese é a resposta à pergunta do tema.', True), ('É melhor deixar a redação para os últimos 15 minutos da prova.', False), ('É recomendável ter um argumento e um repertório em cada desenvolvimento.', True), ('O texto definitivo deve ser escrito a caneta preta.', True)]),
     C('Associe cada etapa ao que se faz nela:', [('chuva de ideias', 'anotar livremente tudo o que se sabe sobre o tema'), ('tese', 'resposta ao tema em uma frase'), ('roteiro', 'resumo do que vai em cada parágrafo'), ('rascunho', 'primeira versão completa do texto'), ('passar a limpo', 'copiar a versão revisada na folha de redação')]),
     A('Organize as etapas na ordem correta (1 a 5): ( ) passar a limpo ( ) chuva de ideias ( ) roteiro ( ) leitura da proposta ( ) rascunho', '5 – 2 – 3 – 1 – 4.'),
     A('Transforme em pergunta o tema “Manipulação do comportamento do usuário pelo controle de dados na internet” (ENEM 2018) e responda-a com uma tese.', 'Ex.: Como o controle de dados na internet manipula o comportamento dos usuários? Tese: a coleta de dados permite que empresas direcionem conteúdos e anúncios, influenciando escolhas sem que o usuário perceba, o que exige regulação e educação digital.', 3),
     A('Monte o roteiro (uma linha para cada parágrafo) de uma redação sobre “Desafios para a valorização da herança africana no Brasil” (2024).', 'Resposta pessoal. Ex.: Introdução: Lei Áurea (1888) + tese: o racismo dificulta a valorização + anúncio: herança da escravidão e pouca presença na escola. D1: escravidão e marginalização da população negra. D2: aplicação insuficiente da Lei 10.639/2003 nas escolas. Conclusão: MEC + formação de professores e materiais didáticos + valorizar a cultura afro-brasileira.', 4),
  ],
  producao='Faça o planejamento completo de uma redação sobre o tema “Desafios para a inclusão de pessoas com deficiência no mercado de trabalho brasileiro” (ou outro tema indicado pelo professor): palavras-chave e pergunta do tema; chuva de ideias; tese; dois argumentos com um repertório cada; proposta com os 5 elementos; roteiro com uma linha para cada parágrafo.')

E(72, B, 'Revisão e reescrita: autoavaliação com a grade das competências',
  aquecimento='Pensem em algo que vocês fizeram várias vezes até ficar bom (um desenho, uma receita, uma jogada, um trabalho): o que mudou da primeira para a última tentativa, e quem ajudou vocês a melhorar?',
  quadro=['# Por que revisar e reescrever',
    '- Nenhum texto nasce pronto: revisar é reler com olhar de corretor; reescrever é melhorar o texto a partir do que foi encontrado.',
    '# Checklist por competência',
    '- C1: Há erros de concordância, regência, crase, acentuação ou vírgula? Há marcas de oralidade, gírias ou abreviações?',
    '- C2: O texto trata do tema com o recorte certo? É dissertativo-argumentativo? Tem repertório produtivo?',
    '- C3: A tese está clara? Os dois argumentos defendem a tese, sem contradições nem repetições?',
    '- C4: Há conectivos variados e adequados entre e dentro dos parágrafos? As palavras do tema foram retomadas sem repetição?',
    '- C5: A proposta tem agente, ação, meio/modo, finalidade e detalhamento? Respeita os direitos humanos? Está ligada aos argumentos?',
    '# Revisão em etapas',
    '- 1ª leitura (sentido): o texto responde ao tema? A ordem das ideias faz sentido? Falta explicar algo?',
    '- 2ª leitura (coesão): os parágrafos estão ligados? Os conectivos estão certos? Há repetições?',
    '- 3ª leitura (gramática): concordância, acentos, vírgulas, crase, ortografia. Leia devagar, frase por frase.',
    '# Correção entre colegas',
    '- Troque a redação com um colega e use a grade das competências: aponte um ponto forte e dois pontos a melhorar.',
    '- Comente o texto, e não a pessoa: “O D2 precisa de um exemplo” (e não “Você escreve mal”).',
    '- Sugira soluções: “Que tal começar o D2 com ‘Além disso’?”.',
    '# Reescrita a partir dos comentários do professor',
    '- Leia todos os comentários e as notas por competência; identifique o tipo de erro que mais se repete.',
    '- Reescreva o texto inteiro (ou o parágrafo indicado), corrigindo os problemas, e não apenas as palavras marcadas.',
    '- Monte uma lista pessoal de “meus erros frequentes” e consulte-a antes de cada nova redação.',
    '# Fique atento',
    '- Revise no rascunho, antes de passar a limpo: na folha de redação, as rasuras devem ser evitadas.',
    '- Se errar na folha definitiva, risque a palavra com um traço simples e escreva a forma correta logo em seguida.',
    '- Reescrever não é castigo: cada reescrita é um treino para a prova.'],
  q=[M('Na revisão em etapas, a 1ª leitura deve verificar:', ['o sentido: se o texto responde ao tema e se as ideias estão em ordem', 'apenas os acentos e as vírgulas, uma palavra de cada vez', 'apenas a letra, o capricho e a limpeza da folha', 'o número exato de palavras de cada parágrafo do texto'], 0),
     M('Qual sequência corresponde à revisão em etapas estudada?', ['sentido → coesão → gramática', 'gramática → título → caligrafia', 'coesão → passar a limpo → sentido', 'caligrafia → sentido → contagem de linhas'], 0),
     M('A pergunta “A proposta tem agente, ação, meio, finalidade e detalhamento?” faz parte do checklist de qual competência?', ['Competência 5', 'Competência 1', 'Competência 2', 'Competência 4'], 0),
     T('Tema: “Desafios para a valorização da pessoa idosa no Brasil”. '
       '(1) Hoje em dia, muito se fala sobre os idosos. Eles são muito importantes para a sociedade. '
       '(2) Em primeiro lugar, muitos idosos são abandonados pelas famílias. Tipo, eles ficam sozinhos em casa e ninguém visita eles. Isso é muito triste, e todo mundo sabe que é errado. '
       '(3) Além disso, o Estatuto da Pessoa Idosa, de 2003, garante direitos a quem tem 60 anos ou mais. No entanto, muitos idosos enfrentam filas, desrespeito e falta de atendimento adequado nos serviços públicos, o que mostra que a lei nem sempre é cumprida. '
       '(4) Portanto, o governo deve fazer alguma coisa para resolver esse problema.',
       fonte='Texto elaborado para esta atividade, com problemas propositais.', titulo='Redação de um estudante (para avaliar)', para=5),
     M('Qual é o principal problema do parágrafo (1)?', ['começa com um clichê e não apresenta tese nem anúncio dos argumentos', 'usa repertórios demais, um atrás do outro, sem nenhuma explicação', 'apresenta uma proposta de intervenção completa fora do lugar', 'traz uma citação inventada e atribuída ao autor errado'], 0),
     A('Encontre no parágrafo (2) dois desvios de linguagem (Competência 1) e corrija-os.', '“Tipo” (marca de oralidade: retirar ou trocar por “Por exemplo,”) e “ninguém visita eles” (→ “ninguém os visita”). Também vale: “todo mundo sabe” (informal; retirar ou trocar por “sabe-se”).', 2),
     M('Qual parágrafo está mais bem desenvolvido, com repertório e explicação?', ['o parágrafo (3)', 'o parágrafo (1)', 'o parágrafo (2)', 'o parágrafo (4)'], 0),
     A('Escreva um comentário de colega para o parágrafo (3): um ponto forte e um ponto a melhorar.', 'Resposta pessoal. Ex.: Ponto forte: usa bem o Estatuto da Pessoa Idosa e mostra, com exemplos, que a lei não é cumprida. A melhorar: o parágrafo poderia terminar com um fechamento que ligue o argumento à tese.', 2),
     A('Reescreva a conclusão (parágrafo 4) com uma proposta de intervenção completa.', 'Resposta pessoal. Ex.: Portanto, o abandono familiar e o descumprimento do Estatuto da Pessoa Idosa ainda impedem a valorização dos idosos. Para mudar esse cenário, as prefeituras, em parceria com ONGs, devem ampliar os centros de convivência para idosos, por meio de atividades culturais, atendimento de saúde e transporte gratuito, a fim de combater o isolamento e garantir seus direitos.', 4),
     M('Qual comentário de correção entre colegas é mais adequado?', ['“Seu D2 tem um bom argumento, mas falta um exemplo para comprová-lo.”', '“Seu texto está horrível, e você escreve muito mal.”', '“Não entendi nada do que você quis dizer; refaça tudo.”', '“Está ótimo!”, sem apontar nenhum ponto a melhorar.'], 0),
     M('Ao receber a redação corrigida pelo professor, o melhor caminho é:', ['ler os comentários, identificar os erros mais frequentes e reescrever o texto', 'guardar a folha na mochila sem ler os comentários do professor', 'corrigir só as palavras marcadas e jogar o resto do texto fora', 'copiar a redação de um colega que tirou uma nota mais alta'], 0),
     M('Se errar uma palavra na folha definitiva do ENEM, o participante deve:', ['passar um traço simples sobre ela e escrever a forma correta em seguida', 'rabiscar a palavra várias vezes, até ela ficar ilegível', 'colocar a palavra errada entre parênteses e seguir em frente', 'escrever a palavra correta por cima da errada, sem riscar'], 0),
     VF('Marque V ou F sobre a revisão e a reescrita:', [('É melhor revisar no rascunho, antes de passar a limpo.', True), ('Na correção entre colegas, o comentário deve criticar a pessoa, e não o texto.', False), ('Reescrever o texto ajuda a não repetir os mesmos erros.', True), ('A revisão gramatical deve ser feita de uma só vez, lendo bem rápido.', False), ('Uma lista de “meus erros frequentes” ajuda nas próximas redações.', True)]),
     C('Associe o problema encontrado à competência em que ele é avaliado:', [('“a gente” e “né” no texto', 'Competência 1'), ('repertório sem relação com o tema', 'Competência 2'), ('argumentos soltos, que não defendem a tese', 'Competência 3'), ('conectivo com sentido trocado', 'Competência 4'), ('proposta que desrespeita os direitos humanos', 'Competência 5')]),
     A('Um professor escreveu na redação de um aluno: “Introdução sem tese.” Explique o que o aluno deve fazer ao reescrever.', 'Deve acrescentar à introdução uma frase com o seu ponto de vista sobre o tema (a tese) e, de preferência, anunciar os dois argumentos que vai desenvolver.', 2),
     A('Qual é a diferença entre revisar e reescrever um texto?', 'Revisar é reler o texto procurando problemas (de sentido, de coesão e de gramática); reescrever é produzir uma nova versão, corrigindo e melhorando o que foi encontrado.', 2),
     A('Revise a frase em três etapas (sentido, coesão e gramática) e reescreva-a: “Os jovem hoje em dia não lê, onde a internet atrapalha muito, né.”', 'Ex.: Muitos jovens leem pouco atualmente, pois a internet disputa a atenção deles com os livros.', 2),
  ],
  producao='Escolha o parágrafo mais fraco da sua redação (ou o parágrafo 2 do texto da folha) e reescreva-o aplicando o checklist das competências, em 8 a 10 linhas. Depois, em uma ou duas linhas, explique o que você mudou e por quê.')
